import{C as e,H as t,R as n,S as r,Z as i,v as a,w as o,x as s}from"./vue-BDYVXuuN.js";import{c}from"./app-m3La2wLh.js";var l=JSON.parse(`{"path":"/courses/zsb-english/l/16/","title":"第 16 课 · 特殊句式 Special Structures | 备考·英语","lang":"zh-CN","frontmatter":{"title":"第 16 课 · 特殊句式 Special Structures","createTime":"2026-09-09T22:39:43.000Z","permalink":"/courses/zsb-english/l/16/","banner":"/images/covers/zsb-english.png","description":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 01 · 语法专题 / 第十六课 语法专题 · 第十六课 对应教材上册 P188–204 · 感叹句、祈使句、强调句、倒装句、反义疑问句五大句式一次讲透，附课件综合练习 15 题。 考点地图 · 点击跳转 感叹句：中心词判 what/how 祈使句：动词原形或 let 开头 强调...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"第 16 课 · 特殊句式 Special Structures\\",\\"image\\":[\\"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png\\"],\\"dateModified\\":\\"2026-10-07T13:23:39.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/16/"}],["meta",{"property":"og:site_name","content":"知序"}],["meta",{"property":"og:title","content":"第 16 课 · 特殊句式 Special Structures"}],["meta",{"property":"og:description","content":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 01 · 语法专题 / 第十六课 语法专题 · 第十六课 对应教材上册 P188–204 · 感叹句、祈使句、强调句、倒装句、反义疑问句五大句式一次讲透，附课件综合练习 15 题。 考点地图 · 点击跳转 感叹句：中心词判 what/how 祈使句：动词原形或 let 开头 强调..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-07T13:23:39.000Z"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:image:src","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"name":"twitter:image:alt","content":"第 16 课 · 特殊句式 Special Structures"}],["meta",{"property":"article:modified_time","content":"2026-10-07T13:23:39.000Z"}],["link",{"rel":"canonical","href":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/16/"}]]},"readingTime":{"minutes":74.72,"words":22416},"git":{"createdTime":1791379419000,"updatedTime":1791379419000,"contributors":[{"name":"38623","username":"","email":"386239680@qq.com","commits":1,"avatar":"https://gravatar.com/avatar/6a2940d3ff3182b82cb8a2c8dfebb295d647509713aef8bc86fb9e95a6767f99?d=retro"}]},"autoDesc":true,"filePathRelative":"courses/zsb-english/l/16.md","headers":[]}`),u={name:`16.md`};function d(c,l,u,d,f,p){let m=t(`VPLink`);return n(),s(`div`,null,[a(`blockquote`,null,[a(`p`,null,[l[1]||=e(`这是本课阅读版。`,-1),o(m,{href:`/blog/lessons/zsb-english/lessons/0016-special-structures.html`},{default:i(()=>[...l[0]||=[a(`strong`,null,`打开互动课程`,-1)]]),_:1}),l[2]||=e(`即可在同一页阅读、作答与复习，学习记录保存在此设备。`,-1)])]),a(`p`,null,[o(m,{href:`/blog/lessons/zsb-english/lessons/course.html`},{default:i(()=>[...l[3]||=[e(`课程总览`,-1)]]),_:1}),l[4]||=e(` / 01 · 语法专题 / 第十六课`,-1)]),l[10]||=r(`<p>语法专题 · 第十六课</p><p>对应教材上册 P188–204 · 感叹句、祈使句、强调句、倒装句、反义疑问句五大句式一次讲透，附课件综合练习 15 题。</p><div class="hint-container info"><p class="hint-container-title">考点地图 · 点击跳转</p><ol><li><a href="#pt-1"><strong>感叹句</strong>：中心词判 what/how</a></li><li><a href="#pt-2"><strong>祈使句</strong>：动词原形或 let 开头</a></li><li><a href="#pt-3"><strong>强调句</strong>：It is/was...that/who...，删除框架验完整</a></li><li><a href="#pt-4"><strong>倒装句</strong>：全倒装/部分倒装</a></li><li><a href="#pt-5"><strong>反义疑问句</strong>：前肯后否、前否后肯，再处理特殊主语与谓语</a></li></ol></div><h2 id="第一部分-·-感叹句" tabindex="-1"><a class="header-anchor" href="#第一部分-·-感叹句"><span>第一部分 · 感叹句</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第一部分 · 感叹句</p><ul><li><strong>目标</strong>：解决“句首填 what 还是 how”：先划掉句末的主谓，看剩下部分的中心词是名词还是形容词/副词，再检查单数可数名词带没带 a/an。</li><li><strong>建议用时</strong>：11 分钟</li><li><strong>知识点</strong>：<code>感叹句 what / how</code></li></ul></div><h3 id="第一部分-·-感叹句-·-小步学" tabindex="-1"><a class="header-anchor" href="#第一部分-·-感叹句-·-小步学"><span>第一部分 · 感叹句 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>特殊句式：在普通句上调整表达重点</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>划掉主谓看中心词：名词 what，形副 how</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：用两步法（划主谓 → 看中心词）解释一道 what 题和一道 how 题的区别，并说清 a/an 什么时候必须出现。</p><div class="hint-container tip"><p class="hint-container-title">划掉主谓看中心词：名词 what，形副 how</p><p><strong>句意</strong>：What an interesting life he lives! 意思是“他过着多么有趣的生活啊”；How amazing the tiny cells are! 意思是“这些微小的细胞多么神奇啊”。</p><p><strong>拆解</strong></p><ul><li>What an interesting life he lives!：划掉句末的主谓 he lives，剩下 What an interesting life，中心词 life 是可数名词单数 → 用 what，且 interesting 以元音音素开头用 an</li><li>How amazing the tiny cells are!：划掉 the tiny cells are，剩下 How amazing，中心词是形容词 amazing → 用 how</li><li>How fast he runs!、How time flies! 是 how 的另两种形式（接副词或直接接主谓）</li><li>What delicious food it is! 里 food 不可数，不加 a/an</li></ul><p><strong>语法</strong>：感叹句主要由 what 或 how 引导：what + 名词（单数可数名词要带 a/an），how + 形容词或副词；另有 How + adj. + a/an + 单数名词（How kind a man he is!）和 How + 主语 + 谓语（How time flies!）。</p><p>正例：What a beautiful princess she is!；What lovely children they are!；How fast he runs!；How kind a man he is! 反例：How interesting life he lives! ×（中心词是名词 life，要用 what）；What amazing the tiny cells are! ×（中心词是形容词 amazing，要用 how） 适用边界：判断只两步：先划主谓，再看中心词。要注意中心词是“被形容词修饰的名词”（名词）还是单独的形容词/副词；单数可数名词前别忘了 a/an。</p><p><strong>口诀</strong>：形副 how，名词 what；可数单数 a/an 莫忘 —— 把句子末尾的“主语 + 谓语”划掉，剩下的第一个实词就是中心词；它决定用哪个引导词。</p></div><p>感叹句用来表达惊讶、喜悦、愤怒、悲伤等强烈情感，主要由 <strong>what</strong> 或 <strong>how</strong> 引导。判断口令：划掉句末&quot;主语 + 谓语&quot;后，<strong>中心词是名词用 what，是形容词/副词用 how</strong>。</p><h3 id="_1-what-引导-中心词是名词" tabindex="-1"><a class="header-anchor" href="#_1-what-引导-中心词是名词"><span>1. what 引导：中心词是名词</span></a></h3><table><thead><tr><th>名词类型</th><th>结构</th><th>例句</th></tr></thead><tbody><tr><td>可数名词单数</td><td>What + a/an + adj. + n. (+ 主语 + 谓语)!</td><td><strong>What a</strong> beautiful princess she is! 多么漂亮的公主啊！</td></tr><tr><td>可数名词复数</td><td>What + adj. + n.-pl. (+ 主语 + 谓语)!</td><td><strong>What</strong> lovely children they are! 多么可爱的孩子们啊！</td></tr><tr><td>不可数名词</td><td>What + adj. + 不可数 n. (+ 主语 + 谓语)!</td><td><strong>What</strong> delicious food it is! 多么美味的食物啊！</td></tr></tbody></table><h3 id="_2-how-引导-中心词是形容词或副词" tabindex="-1"><a class="header-anchor" href="#_2-how-引导-中心词是形容词或副词"><span>2. how 引导：中心词是形容词或副词</span></a></h3><table><thead><tr><th>结构</th><th>例句</th></tr></thead><tbody><tr><td>How + adj./adv. (+ 主语 + 谓语)!</td><td><strong>How fast</strong> he runs! 他跑得多么快啊！</td></tr><tr><td>How + adj. + a/an + 单数名词 (+ 主语 + 谓语)!</td><td><strong>How kind a</strong> man he is! 他是多么善良的人啊！</td></tr><tr><td>How + 主语 + 谓语!</td><td><strong>How</strong> time flies! 时间过得真快啊！</td></tr></tbody></table><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>做题方法划掉句末的&quot;主语 + 谓语&quot;，看剩余部分的中心词：<strong>名词用 what，形容词/副词用 how</strong>。单数可数名词前还要有 a/an。</p></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀<strong>感叹句，并不难；what/how 放最前。形副跟在 how 后面，what 身后名词连；名词若是可数单，前带冠词 a 或 an；主谓放在最后面，省略它们很常见。</strong></p></div><h2 id="第二部分-·-祈使句" tabindex="-1"><a class="header-anchor" href="#第二部分-·-祈使句"><span>第二部分 · 祈使句</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第二部分 · 祈使句</p><ul><li><strong>目标</strong>：解决祈使句的两种开头与三种否定：动词原形、let 结构，以及 Let&#39;s not 与 Don&#39;t let 的分工。</li><li><strong>建议用时</strong>：10 分钟</li><li><strong>知识点</strong>：<code>祈使句（动词原形 / let 结构）</code></li></ul></div><h3 id="第二部分-·-祈使句-·-小步学" tabindex="-1"><a class="header-anchor" href="#第二部分-·-祈使句-·-小步学"><span>第二部分 · 祈使句 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 3 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>特殊句式：在普通句上调整表达重点</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>动词原形开头；let 的否定分人称</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：说出祈使句的肯定式、否定式各两种写法，并解释 Let&#39;s 与 Let us 的差别。</p><div class="hint-container tip"><p class="hint-container-title">动词原形开头；let 的否定分人称</p><p><strong>句意</strong>：Let&#39;s not stay with him later. 意思是“我们之后不要和他待在一起”；Don&#39;t let him disturb you. 意思是“不要让他打扰你”。</p><p><strong>拆解</strong></p><ul><li>肯定祈使句直接用动词原形：Open the door. / Please come here.</li><li>否定用 Don&#39;t / Never + 动词原形：Don&#39;t be late. / Never touch the machine.</li><li>let 后是第一人称的否定用 Let&#39;s / Let us / Let me + not + 动词原形</li><li>let 后是第三人称的否定用 Don&#39;t let + 宾语 + 动词原形</li></ul><p><strong>语法</strong>：祈使句表达命令、请求、劝告、警告或禁止，主语 you 通常省略：肯定用动词原形，否定用 Don&#39;t / Never + 动词原形；let 结构为 Let + 宾语 + 动词原形，第一人称否定用 Let&#39;s not do，第三人称否定用 Don&#39;t let sb. do。</p><p>正例：Open the door. / Please come here.；Don&#39;t be late. / Never touch the machine.；Let&#39;s not stay with him later.；Don&#39;t let him disturb you. 反例：Let&#39;s don&#39;t stay with him later. ×（第一人称否定说 Let&#39;s not）；Don&#39;t let&#39;s him disturb you. ×（第三人称否定用 Don&#39;t let him…） 适用边界：Let&#39;s 与 Let us 不完全相同：Let&#39;s 包含听话人，附加问句用 shall we；Let us 常是请求对方允许“我们”做，附加问句用 will you。</p><p><strong>口诀</strong>：第一人称 Let&#39;s not，第三人称 Don&#39;t let —— 先看 let 后面的人称：包含“我们”用 Let&#39;s not，指“他/她/他们”就用 Don&#39;t let。</p></div><p>祈使句表达命令、请求、劝告、警告或禁止，<strong>主语 you 通常省略</strong>。</p><h3 id="_1-动词原形开头" tabindex="-1"><a class="header-anchor" href="#_1-动词原形开头"><span>1. 动词原形开头</span></a></h3><p>肯定：<strong>动词原形...</strong>，可加 please；否定：<strong>Don&#39;t / Never + 动词原形...</strong></p><p>Open the door. 打开门。 Please come here. 请到这里来。 <strong>Don&#39;t</strong> be late. 不要迟到。 <strong>Never</strong> touch the machine. 绝不要碰这台机器。</p><h3 id="_2-let-开头" tabindex="-1"><a class="header-anchor" href="#_2-let-开头"><span>2. let 开头</span></a></h3><ol><li>肯定：<strong>Let + 宾语 + 动词原形</strong></li><li>let 后是第一人称的否定：<strong>Let&#39;s / Let us / Let me + not + 动词原形</strong></li><li>let 后是第三人称的否定：通常 <strong>Don&#39;t let + 宾语 + 动词原形</strong></li></ol><p>Let&#39;s (Let us) go shopping. 我们去购物吧。 Let it go. 随它去吧。 <strong>Let&#39;s not</strong> stay with him later. 我们之后不要和他待在一起。 <strong>Don&#39;t let</strong> him disturb you. 不要让他打扰你。</p><div class="hint-container caution"><p class="hint-container-title">易错</p><p>Let&#39;s 和 Let us 不完全相同<strong>Let&#39;s</strong> 通常包含听话人，反义疑问句用 <strong>shall we</strong>；<strong>Let us</strong> 常是请求对方允许&quot;我们&quot;做，反义疑问句用 <strong>will you</strong>。</p></div><h2 id="第三部分-·-强调句" tabindex="-1"><a class="header-anchor" href="#第三部分-·-强调句"><span>第三部分 · 强调句</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第三部分 · 强调句</p><ul><li><strong>目标</strong>：解决“It is/was … that/who …”到底是不是强调句：先用删除检验判定结构，再处理 not…until 的强调、谓语强调与 It 易混句型。</li><li><strong>建议用时</strong>：12 分钟</li><li><strong>知识点</strong>：<code>强调句 It is/was…that/who…</code> <code>not…until 的强调与 do 强调谓语</code> <code>It 易混句型（since / before / when / first time）</code></li></ul></div><h3 id="第三部分-·-强调句-·-小步学" tabindex="-1"><a class="header-anchor" href="#第三部分-·-强调句-·-小步学"><span>第三部分 · 强调句 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>特殊句式：在普通句上调整表达重点</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>删框检验：删掉 It is/was 与 that/who，还完整才是强调句</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>not…until 的强调，与 do 强调谓语</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>It 易混句型：since、before、when 与“第几次”</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：用“删除检验”判断一道 It 句子是不是强调句，并说出 not…until 强调句与 do 强调谓语各自的写法。</p><div class="hint-container tip"><p class="hint-container-title">删框检验：删掉 It is/was 与 that/who，还完整才是强调句</p><p><strong>句意</strong>：It was in the room that we used to have meetings. 意思是“我们过去正是在这个房间开会”。</p><p><strong>拆解</strong></p><ul><li>It was + in the room + that + we used to have meetings：被强调的是地点状语 in the room</li><li>删去 It was 和 that 后，剩下 We used to have meetings in the room. 仍是完整句 → 强调句</li><li>It is clear that not all boys like football. 删框架后只剩 not all boys like football，不完整 → 主语从句</li><li>It was a room where we used to have meetings. 里 where 引导定语从句，不是强调句</li></ul><p><strong>语法</strong>：强调句基本结构：It is/was + 被强调部分 + that/who + 其余部分。三条铁律：只能用 It is / It was；强调人可用 that 或 who，强调非人部分只能用 that；It 无实义，不能强调谓语动词。</p><p>正例：It was I who/that bought a quilt in the shop yesterday.（强调主语）；It was a quilt that I bought in the shop yesterday.（强调宾语）；It was in the shop that I bought a quilt yesterday.（强调地点）；It was yesterday that I bought a quilt in the shop.（强调时间） 反例：It were in the shop that I bought a quilt. ×（只能用 It is/was）；It is clear that not all boys like football. 当成强调句 ×（删框架后不完整，是主语从句） 适用边界：先做删除检验再填 that：It is important that…、It was a room where… 这些看着像，其实是主语从句和定语从句。</p><p><strong>口诀</strong>：It is/was 框起来，删框完整才算对 —— 把 It is/was 和 that/who 都划掉，剩下的部分能不能独立成句——能，才是强调句。</p></div><div class="hint-container tip"><p class="hint-container-title">not…until 的强调，与 do 强调谓语</p><p><strong>句意</strong>：It was not until his wife came back that he went to bed. 意思是“直到妻子回来，他才睡觉”；Mary does like surfing the Internet. 意思是“玛丽确实喜欢上网”。</p><p><strong>拆解</strong></p><ul><li>普通句 He didn&#39;t go to bed until his wife came back. 强调 not...until → It was not until his wife came back that he went to bed.</li><li>强调句里只用 until，that 后面改成肯定形式 he went to bed</li><li>谓语动词本身要强调时不用 It 结构，用助动词 do/does/did + 动词原形：Mary does like surfing the Internet.</li><li>It was because of his good performance at the interview that he got the job. 强调的是原因状语</li></ul><p><strong>语法</strong>：强调 not...until 用 It is/was not until + 被强调部分 + that + 肯定形式的其余部分；强调谓语动词用 do/does/did + 动词原形，不用 It 强调结构。</p><p>正例：It was not until she arrived home that she remembered her appointment.；It was because of his good performance that he got the job.；Mary does like surfing the Internet. 反例：It was not until she arrived home that she didn&#39;t remember her appointment. ×（that 后用肯定形式）；It is Mary that likes surfing the Internet 用来强调谓语 ×（It 结构不能强调谓语，要用 does like） 适用边界：强调句的 that 不是“看见 It 就填 that”：先做删除检验；另外 not until 的倒装写法是“前不倒、后倒”，与强调句写法要分清。</p><p><strong>口诀</strong>：It 框不进谓语，强调谓语请 do 帮忙 —— 强调主语、宾语、状语用 It is/was…that…；强调“确实做了”这个动作，用 do/does/did。</p></div><div class="hint-container tip"><p class="hint-container-title">It 易混句型：since、before、when 与“第几次”</p><p><strong>句意</strong>：It has been more than five years since they met last time in Wuhan. 意思是“自从他们上次在武汉见面，已经五年多了”。</p><p><strong>拆解</strong></p><ul><li>It is/has been + 时间段 + since + 一般过去时：自从……已有多久</li><li>It was (not) + 时间段 + before + 一般过去时：过了很久才／没过多久就</li><li>It will (not) be + 时间段 + before + 一般现在时：要过多久才</li><li>It is/was the first time that + 现在完成时/过去完成时；It is (high) time that + 过去式或 should do</li></ul><p><strong>语法</strong>：It 作形式主语的句型要按固定搭配记：since 管“已经多久”，before 管“过多久才”，the first time 管“第几次”（现在用现在完成时、过去用过去完成时），It is time 管“该做某事了”（从句用过去式或 should do）。</p><ol><li>since：从句用一般过去时 —→ 主句用现在完成时</li><li>before：主句 was/will be + 时间段 —→ 从句用一般过去时/一般现在时</li></ol><p>正例：It&#39;s ten years since he came to Shanghai.；It was not long before the police arrived at the scene.；It will be days before they finish their homework.；It is the first time that I have visited the city.；It is high time that she went/should go to school to pick up her daughter. 反例：It is ten years since he has come to Shanghai. ×（since 从句用一般过去时）；It will be days before they will finish their homework. ×（before 从句用一般现在时） 适用边界：先看框架：“时间段 + since”讲已经过去多久，“时间段 + before”讲要过多久才，“the first time”讲第几次——三套时态各不相同，不要用一个模子套。</p><p><strong>口诀</strong>：since 管已经多久，before 管要过多久，the first time 用完成时 —— 先认框架词，再套对应时态，最后检查从句是过去时还是现在时。</p></div><h3 id="_1-基本结构" tabindex="-1"><a class="header-anchor" href="#_1-基本结构"><span>1. 基本结构</span></a></h3><p><strong>It is/was + 被强调部分 + that/who + 其余部分</strong>。三条铁律：只能用 <strong>It is / It was</strong>（不用 It were，也不随意换时态）；强调<strong>人</strong>时可用 that 或 who，强调<strong>非人</strong>部分只能用 that；It 无实义，该结构<strong>不能强调谓语动词</strong>。</p><p>【补充讲解】谓语动词本身要强调时，不用 It 结构，而用助动词 <strong>do / does / did + 动词原形</strong>：Mary <strong>does</strong> like surfing the Internet.（玛丽确实喜欢上网。）——练习第 34 题考的就是这个。</p><p>以 I bought a quilt in the shop yesterday.（我昨天在商店买了一床被子。）为例：</p><p>It was <strong>I</strong> who/that bought a quilt in the shop yesterday. 正是我昨天在商店买了一床被子。（强调主语）</p><p>It was <strong>a quilt</strong> that I bought in the shop yesterday. 我昨天在商店买的正是一床被子。（强调宾语）</p><p>It was <strong>in the shop</strong> that I bought a quilt yesterday. 我昨天正是在商店买了一床被子。（强调地点）</p><p>It was <strong>yesterday</strong> that I bought a quilt in the shop. 我正是昨天在商店买了一床被子。（强调时间）</p><h3 id="_2-not-until-的强调" tabindex="-1"><a class="header-anchor" href="#_2-not-until-的强调"><span>2. not...until 的强调</span></a></h3><p><strong>It is/was not until + 被强调部分 + that + 肯定形式的其余部分</strong>（强调句里只用 until，that 后改为肯定）。</p><p>He didn&#39;t go to bed until/till his wife came back. 他直到妻子回来才睡觉。（普通句，till/until 均可）</p><p><strong>It was not until</strong> his wife came back <strong>that</strong> he went to bed. 直到妻子回来，他才睡觉。</p><h3 id="_3-疑问句的强调" tabindex="-1"><a class="header-anchor" href="#_3-疑问句的强调"><span>3. 疑问句的强调</span></a></h3><ul><li>一般疑问句：<strong>Is/Was it + 被强调部分 + that/who + 其余部分（陈述语序）?</strong></li><li>特殊疑问句：<strong>特殊疑问词 + is/was it + that + 其余部分（陈述语序）?</strong></li></ul><p><strong>Was it</strong> Tom <strong>that</strong> won the prize? 是汤姆赢得了这个奖吗？ <strong>When was it that</strong> you met the pop star? 你究竟是什么时候遇见那位流行歌星的？</p><h3 id="_4-判断方法-删掉强调框架" tabindex="-1"><a class="header-anchor" href="#_4-判断方法-删掉强调框架"><span>4. 判断方法：删掉强调框架</span></a></h3><p>删去 <strong>It is/was</strong> 和 <strong>that/who</strong> 后，剩余部分<strong>仍是完整句子</strong>，才是强调句。</p><table><thead><tr><th>句子</th><th>判断</th></tr></thead><tbody><tr><td>It is near the CBD that accidents often occur. 事故常在中央商务区附近发生。</td><td>删除框架后为完整句，<strong>强调句</strong></td></tr><tr><td>It is clear that not all boys like football. 显然，并非所有男孩都喜欢足球。</td><td>删除框架后不完整，<strong>主语从句</strong></td></tr><tr><td>It was a room where we used to have meetings. 那是我们过去开会的房间。</td><td>where 引导<strong>定语从句</strong></td></tr><tr><td>It was in the room that we used to have meetings. 我们过去正是在这个房间开会。</td><td>强调地点状语，<strong>强调句</strong></td></tr></tbody></table><div class="hint-container caution"><p class="hint-container-title">易错</p><p>强调句的 that 不是&quot;看见 It 就填 that&quot;先做删除检验；It is clear that...、It was a room where... 分别是主语从句和定语从句。</p></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀<strong>It is/was 框起来，删框完整才算对。</strong></p></div><h3 id="_5-it-易混句型" tabindex="-1"><a class="header-anchor" href="#_5-it-易混句型"><span>5. It 易混句型</span></a></h3><table><thead><tr><th>结构</th><th>含义/时态</th><th>例句</th></tr></thead><tbody><tr><td>It is/has been + 时间段 + since + 一般过去时</td><td>自从短暂动作发生至今已有多久</td><td>It&#39;s ten years since he came to Shanghai. 他来上海已经十年了。</td></tr><tr><td>同上，since 从句为延续性动词</td><td>从&quot;不再做该事&quot;算起</td><td>It has been three years since Mike was a teacher. 迈克不当老师已经三年了。</td></tr><tr><td>It was + 时间段 + since + 过去完成时</td><td>截止过去某时已有多久</td><td>It was five years since she had left her hometown. 她离开家乡已经五年了。</td></tr><tr><td>It was (not) + 时间段 + before + 一般过去时</td><td>过了很久才/没过多久就</td><td>It was not long before the police arrived at the scene. 没过多久警察就到了现场。</td></tr><tr><td>It will (not) be + 时间段 + before + 一般现在时</td><td>要过多久才/用不了多久就</td><td>It will be days before they finish their homework. 他们要过好几天才能完成作业。</td></tr><tr><td>It was + 时间点 + when + 一般过去时</td><td>当……时是几点</td><td>It was six when he arrived. 他到达时是六点。</td></tr><tr><td>It will be + 时间点 + when + 一般现在时</td><td>当……时将是几点</td><td>It will be midnight when they get there. 他们到达时将是午夜。</td></tr><tr><td>It is/was + 时间状语 + that...</td><td>强调时间</td><td>It was at six that he arrived. 他正是在六点到达。</td></tr><tr><td>It is (high/about) time + that + 过去式 / should do</td><td>到该做……的时候了</td><td>It is high time that she went/should go to school to pick up her daughter. 她该去学校接女儿了。</td></tr><tr><td>It is/will be the first/second...time + that + 现在完成时</td><td>现在/将来第几次</td><td>It is the first time that I have visited the city. 这是我第一次游览这座城市。</td></tr><tr><td>It was the first/second...time + that + 过去完成时</td><td>过去第几次</td><td>It was the first time that I had cooked a meal for my parents. 那是我第一次为父母做饭。</td></tr></tbody></table><h2 id="第四部分-·-倒装句" tabindex="-1"><a class="header-anchor" href="#第四部分-·-倒装句"><span>第四部分 · 倒装句</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第四部分 · 倒装句</p><ul><li><strong>目标</strong>：解决“什么时候倒、倒哪一半”：先分完全倒装与部分倒装，再认否定词首、only 置首、So/Such 前置、as 让步倒装四类触发条件。</li><li><strong>建议用时</strong>：14 分钟</li><li><strong>知识点</strong>：<code>完全倒装（副词 / 介词短语 / 表语置于句首）</code> <code>否定成分置于句首的部分倒装</code> <code>only + 状语置于句首的部分倒装</code> <code>so / neither / nor 的“也一样”与“确实如此”</code> <code>as / though 让步倒装与 so…that 前置倒装</code></li></ul></div><h3 id="第四部分-·-倒装句-·-小步学" tabindex="-1"><a class="header-anchor" href="#第四部分-·-倒装句-·-小步学"><span>第四部分 · 倒装句 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>特殊句式：在普通句上调整表达重点</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>完全倒装：名词主语才倒，代词不倒</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>部分倒装：否定词置首，前不倒后倒、前倒后不倒</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>only + 状语、So/Such 前置、so/neither 也一样</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>as / though 让步倒装：名词提前去冠词</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：用一句话区分完全倒装与部分倒装，再说出 not until、not only、only、as 让步四处倒装各自倒哪一半。</p><div class="hint-container tip"><p class="hint-container-title">完全倒装：名词主语才倒，代词不倒</p><p><strong>句意</strong>：Across the river lies a newly built bridge. 意思是“河对岸横跨着一座新建的桥”；Here comes the bus. 意思是“公交车来了”。</p><p><strong>拆解</strong></p><ul><li>方位介词短语置于句首，整个谓语提到主语前：Across the river lies a newly built bridge.</li><li>主语 a newly built bridge 是名词 → 倒装；newly 是副词，修饰过去分词 built</li><li>Here comes the bus.（名词主语，倒装）／Here we are.（代词主语，不倒装）</li><li>表语置于句首也构成完全倒装：Near the southern end of the village was a large pear orchard.</li></ul><p><strong>语法</strong>：完全倒装把整个谓语放到主语前：时间、方位、方式副词或介词短语置于句首，或表语置于句首时使用；主语是名词才倒装，主语是人称代词时不倒装。课件所考的全倒装通常用一般现在时或一般过去时。</p><p>正例：On the top of the hill stands a temple.；Here comes the bus.；Here we are.（代词主语，不倒装）；Very important in the farmer&#39;s life is the radio weather report. 反例：Here comes it. ×（代词主语不倒装，说 Here it comes.）；Across the river a newly built bridge lies. ×（方位短语置首却没有倒装） 适用边界：完全倒装不借助 do：直接把 be、come、lie、stand 等谓语整个搬到主语前。主语若是 it、we、they 这类代词，句子回到正常语序。</p><p><strong>口诀</strong>：全倒谓语全提前，代词主语不倒装 —— 先看主语是名词还是代词，再看是不是副词或介词短语开了头。</p></div><div class="hint-container tip"><p class="hint-container-title">部分倒装：否定词置首，前不倒后倒、前倒后不倒</p><p><strong>句意</strong>：Not until the baby fell asleep did the mother go to bed. 意思是“直到婴儿睡着，母亲才上床睡觉”；Not only does he study hard, but he also helps others in study. 意思是“他不仅学习努力，还帮助别人学习”。</p><p><strong>拆解</strong></p><ul><li>Never、seldom、hardly、scarcely、little、not until、not only、by no means、under no circumstances 等置于句首时，主句部分倒装</li><li>Hardly had I closed the door when the phone rang.（hardly 配 when）</li><li>No sooner had he sat down than somebody knocked on the door.（no sooner 配 than）</li><li>Not until 前不倒后倒；Not only...but also 前倒后不倒</li></ul><p><strong>语法</strong>：否定或半否定成分置于句首时，主句部分倒装：只把助动词、情态动词或 be 提到主语前，没有这些词时借助 do/does/did。</p><p>正例：Seldom does he go to the cinema.；Hardly had I got home when it began to rain.；Not until the baby fell asleep did the mother go to bed.；Not only does he study hard, but he also helps others in study. 反例：Not until the baby fell asleep the mother went to bed. ×（Not until 后主句要倒装）；No sooner had we arrived at the destination when it started to rain. ×（no sooner 配 than） 适用边界：两类结构的倒装位置相反：not until 只倒后一半，not only 只倒前一半。写之前先数清有几半句子。</p><p><strong>口诀</strong>：Not until 前不倒后倒，not only 前倒后不倒；hardly/scarcely 配 when，no sooner 配 than —— 先记配对词，再记倒装落在哪一半。</p></div><div class="hint-container tip"><p class="hint-container-title">only + 状语、So/Such 前置、so/neither 也一样</p><p><strong>句意</strong>：Only in this way can I go to a good university. 意思是“只有用这种方法，我才能上好大学”；He is a student, and so is she. 意思是“他是学生，她也是”。</p><p><strong>拆解</strong></p><ul><li>only 修饰副词、介词短语或状语从句并置于句首 → 主句部分倒装：Only when the war was over in 1945 did he return to his hometown.</li><li>only 修饰主语不倒装：Only Tom knows the answer.</li><li>So/Such...that 中的 So/Such 置于句首：So fast did he run that I couldn&#39;t catch up with him.／So little did I know about British history that the lecture was completely beyond me.</li><li>So + 助动词 + 新主语 表“也一样”（So did Mary.）；So + 主语 + 助动词 表“确实如此”，不倒装（So she did.）</li></ul><p><strong>语法</strong>：only + 状语置于句首时主句部分倒装，only 修饰主语时不倒装；So/Such...that 中的 So/Such 置于句首时主句部分倒装；So + 助动词 + 新主语表“另一人也一样”，So + 主语 + 助动词表“确实如此”。</p><p>正例：Only in this way can I go to a good university.；So fast did he run that I couldn&#39;t catch up with him.；He doesn&#39;t like playing basketball. Neither/Nor do I.；—It was cold yesterday. —So it was. 反例：Only Tom know the answer. ×（only 修饰主语不倒装，且主语是第三人称单数应说 knows）；So she did, and so did I. 用来表示“她也一样” ×（So + 主语 + 助动词是“确实如此”，不能表别人也一样） 适用边界：so 有两副面孔：倒装的是“别人也一样”，不倒装的是“确实如此”；only 也有两条线：修饰状语倒装，修饰主语不倒装。</p><p><strong>口诀</strong>：So 倒装别人也，So 不倒装确实如此 —— 看到 so 开头的句子先问：说的是“我也是”还是“确实如此”，前者倒装、后者不倒。</p></div><div class="hint-container tip"><p class="hint-container-title">as / though 让步倒装：名词提前去冠词</p><p><strong>句意</strong>：Teacher as she is, she is not capable of teaching all subjects at present. 意思是“尽管她是老师，目前却不能教所有科目”。</p><p><strong>拆解</strong></p><ul><li>表语提前：Apart as they live, they often talk with each other by phone.</li><li>单数可数名词作表语提前时省冠词：Teacher as she is（不说 A teacher as she is）</li><li>动词原形提前：Try as she may, she won&#39;t pass it.</li><li>这与第 14 课 as 让步倒装是同一条规则；no matter how/however 属于成分前置，不是助动词倒装</li></ul><p><strong>语法</strong>：as/though 引导让步从句时，把表语、状语或动词原形提前，结构为“被提前成分 + as/though + 主语 + 谓语”；单数可数名词作表语提前时省略冠词。no matter how / however 把被修饰的形容词、副词移到从句前端，属于成分前置而非助动词倒装。</p><p>正例：Teacher as she is, she is not capable of teaching all subjects.；Apart as they live, they often talk with each other by phone.；Hard as he tried, he couldn&#39;t pass the exam.；Try as she may, she won&#39;t pass it. 反例：A teacher as she is, she is not capable… ×（名词提前要去冠词）；As she is a teacher, she is not capable… ×（as 让步必须倒装，这样写会被读成“因为她/当她是老师”） 适用边界：只有 as/though 有这条倒装；although 永不倒装。看到句首 as 要先看语序：倒装才是“虽然”。</p><p><strong>口诀</strong>：让步 as 必倒装，名词提前去冠词 —— 先判让步关系，再检查语序和冠词这两处。</p></div><p>自然语序是&quot;主语 + 谓语&quot;。倒装分两类：<strong>完全倒装</strong>——整个谓语放到主语前，如 Here comes the bus.；<strong>部分倒装</strong>——只把助动词、情态动词或 be 放到主语前，没有这些词时借助 do/does/did，如 Seldom does he go to the cinema.</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀<strong>全倒谓语全提前，部分只提助情系。</strong></p></div><h3 id="_1-完全倒装" tabindex="-1"><a class="header-anchor" href="#_1-完全倒装"><span>1. 完全倒装</span></a></h3><p><strong>① 时间、方位、方式副词或介词短语置于句首。</strong>常见 here, there, then, down, away, out, on the wall, in the classroom 等。主语是<strong>名词</strong>时全倒装；主语是<strong>人称代词</strong>时不倒装。课件所考全倒装通常用一般现在时或一般过去时。</p><p><strong>On the top of the hill stands</strong> a temple. 山顶上坐落着一座寺庙。</p><p><strong>Here comes</strong> the bus. 公交车来了。（名词作主语，倒装）</p><p>Here <strong>we are</strong>. 我们到了。（代词作主语，不倒装）</p><p><strong>Here is</strong> China&#39;s largest tropical forest. 这里是中国最大的热带森林。（第一场课独有例句）</p><p><strong>② 表语置于句首。</strong>结构为&quot;表语 + 系动词 + 主语&quot;，用于平衡句子、衔接上下文或突出表语。</p><p><strong>Near the southern end of the village was</strong> a large pear orchard. 村子南端附近有一大片梨园。</p><p><strong>Very important in the farmer&#39;s life is</strong> the radio weather report. 广播天气预报对农民生活非常重要。</p><h3 id="_2-部分倒装" tabindex="-1"><a class="header-anchor" href="#_2-部分倒装"><span>2. 部分倒装</span></a></h3><p><strong>① 否定或半否定成分置于句首。</strong>never, seldom, hardly, scarcely, little, not until, by no means, not only, under no circumstances 等置于句首时，主句部分倒装。四个固定搭配：</p><ul><li><strong>Hardly/Scarcely had + 主语 + done when...</strong>：刚……就……</li><li><strong>No sooner had + 主语 + done than...</strong>：一……就……</li><li><strong>Not until + 时间状语/从句 + 倒装主句</strong>：前不倒、后倒</li><li><strong>Not only + 倒装分句, but also + 陈述语序分句</strong>：前倒后不倒</li></ul><p><strong>Seldom does</strong> he go to the cinema. 他很少去电影院。</p><p><strong>Hardly had</strong> I got home <strong>when</strong> it began to rain. 我刚到家就开始下雨。</p><p><strong>No sooner had</strong> we arrived at the destination <strong>than</strong> it started to rain. 我们一到目的地就开始下雨。</p><p><strong>Not until</strong> the baby fell asleep <strong>did</strong> the mother go to bed. 直到婴儿睡着，母亲才上床睡觉。</p><p><strong>Not only does</strong> he study hard, <strong>but</strong> he also helps others in study. 他不仅学习努力，还帮助别人学习。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀<strong>Not until 前不倒后倒，not only 前倒后不倒；hardly/scarcely 配 when，no sooner 配 than。</strong></p></div><p><strong>② only + 状语置于句首。</strong>only 修饰副词、介词短语或状语从句并置于句首时，<strong>主句</strong>部分倒装。</p><p><strong>Only in this way can</strong> I go to a good university. 只有用这种方法，我才能上好大学。</p><p><strong>Only when</strong> the girl left him <strong>did</strong> he realize how deeply he loved her. 只有女孩离开后，他才意识到自己爱她有多深。</p><p><strong>Only after</strong> being asked six times by his mother <strong>did</strong> he get up. 妈妈叫了六次后他才起床。</p><div class="hint-container caution"><p class="hint-container-title">易错</p><p>only 修饰主语不倒装只有 <strong>only + 状语</strong>置于句首才触发倒装；Only Tom knows the answer.（只有汤姆知道答案。）不倒装。</p></div><p><strong>③ So/Such...that 中 So/Such 置于句首。</strong></p><p><strong>So fast did</strong> he run <strong>that</strong> I couldn&#39;t catch up with him. 他跑得如此快，我追不上他。</p><p><strong>Such</strong> an interesting story <strong>is</strong> it <strong>that</strong> we all want to listen to it again. 这个故事如此有趣，我们都想再听一遍。</p><p><strong>④ so / neither / nor 表&quot;也一样&quot;。</strong></p><table><thead><tr><th>上文</th><th>新主语也如此</th><th>结构</th></tr></thead><tbody><tr><td>肯定</td><td>……也一样</td><td>So + 助动词/情态动词/be + 主语</td></tr><tr><td>否定</td><td>……也不</td><td>Neither/Nor + 助动词/情态动词/be + 主语</td></tr></tbody></table><p>He is a student, and <strong>so is</strong> she. 他是学生，她也是。</p><p>John bought an apartment. <strong>So did</strong> Mary. 约翰买了一套公寓，玛丽也买了。</p><p>He doesn&#39;t like playing basketball. <strong>Neither/Nor do</strong> I. 他不喜欢打篮球，我也不喜欢。</p><p>They haven&#39;t been to that city. <strong>Neither/Nor have</strong> we. 他们没去过那座城市，我们也没去过。</p><p>如果只是确认前句&quot;的确如此&quot;，用 <strong>So + 主语 + 助动词</strong>，不倒装：&quot;It was cold yesterday.&quot; &quot;<strong>So it was.</strong>&quot; &quot;昨天很冷。&quot;&quot;确实如此。&quot;</p><div class="hint-container caution"><p class="hint-container-title">易错</p><p>课件原句辨误课件以 Neither/Nor she can 表示&quot;她确实不会&quot;，该结构不规范。确认否定事实宜说 No, she can&#39;t.；若表示另一个人也不会，才用 Neither/Nor can + 新主语。</p></div><p><strong>⑤ 频率/方式状语置于句首（课件所考强调语境）。</strong>Often, Always, Once, Many a time, Now and then, Every other day, Every two hours，以及 well、thus 等在强调或文学语境中置于句首，可用部分倒装。</p><p><strong>Many a time has</strong> he given me good advice. 他多次给我很好的建议。</p><p><strong>Always have</strong> I dreamed of becoming a famous writer. 我一直梦想成为著名作家。</p><p><strong>Thus was</strong> it stolen. 它就是这样被偷走的。</p><p><strong>Well do</strong> I remember the day when we first met. 我清楚地记得我们初次见面的那一天。</p><p><strong>⑥ as/though 引导让步从句。</strong>结构：<strong>adj./adv./n./v. + as/though + 主语 + 谓语</strong>。单数可数名词作表语提前时<strong>省略冠词</strong>。</p><p><strong>Pretty though</strong> she is, she is not clever. 尽管她漂亮，但并不聪明。</p><p><strong>Hard as</strong> he tried, he couldn&#39;t pass the exam. 尽管他努力尝试，仍没通过考试。</p><p><strong>Child as</strong> he is, he can speak English fluently. 尽管还是个孩子，他却能流利说英语。（省略冠词 a）</p><p><strong>Try as</strong> she may, she won&#39;t pass it. 尽管她可能会尝试，但仍无法通过。</p><p><strong>⑦ no matter how/however 与 no matter what/whatever。</strong>形容词、副词或被修饰名词随引导词移到从句前端；这属于<strong>成分前置，并非助动词倒装</strong>。</p><p><strong>No matter how hard</strong> she tried, she always failed in math exams. 无论她多努力，数学考试总是不及格。</p><p><strong>No matter what</strong> difficulties we may encounter, we should never give up. 无论遇到什么困难，我们都不应放弃。</p><p><strong>⑧ 虚拟条件句省略 if。</strong>if 从句含 <strong>were / had / should</strong> 时，可省略 if，并把 were/had/should 提到主语前。</p><p><strong>If it had not been for</strong> my illness, I would have lent him a helping hand. 如果不是我生病了，我本会帮他一把。</p><p><strong>Had it not been for</strong> my illness, I would have lent him a helping hand. （=上句，倒装）</p><p><strong>Were it not for</strong> his encouragement, I wouldn&#39;t keep doing this job. 若不是他的鼓励，我不会继续做这份工作。</p><h2 id="第五部分-·-反义疑问句" tabindex="-1"><a class="header-anchor" href="#第五部分-·-反义疑问句"><span>第五部分 · 反义疑问句</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第五部分 · 反义疑问句</p><ul><li><strong>目标</strong>：解决附加问句的三步：先判句法肯否，再对主句还是宾语从句，最后挑对助动词与人称。</li><li><strong>建议用时</strong>：13 分钟</li><li><strong>知识点</strong>：<code>反义疑问句的基本原则与特殊主语</code> <code>ought to / used to / have / need / must 的附加问句</code> <code>祈使句与 there be 的附加问句</code> <code>主从复合句与否定前移的附加问句</code></li></ul></div><h3 id="第五部分-·-反义疑问句-·-小步学" tabindex="-1"><a class="header-anchor" href="#第五部分-·-反义疑问句-·-小步学"><span>第五部分 · 反义疑问句 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>特殊句式：在普通句上调整表达重点</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>前肯后否、前否后肯；再把特殊主语对号入座</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>used to、have、need、must 的附加问句</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>主从复合句看谁、否定前移，以及祈使句的附加问</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：用三步讲清一道反义疑问句的作法：判肯否 → 对主句还是宾语从句 → 挑对助动词与人称。</p><div class="hint-container tip"><p class="hint-container-title">前肯后否、前否后肯；再把特殊主语对号入座</p><p><strong>句意</strong>：Judy hardly joins in any class activities, does she? 意思是“朱迪几乎不参加任何班级活动，是吗？”</p><p><strong>拆解</strong></p><ul><li>陈述部分 hardly 已有否定含义 → 附加问句用肯定式 does she</li><li>joins 是一般现在时的实义动词 → 借 does</li><li>I am 的附加问句用 aren&#39;t I；everybody/someone 用 they；everything/this/that 用 it；these/those 用 they</li><li>He was unsuccessful, wasn&#39;t he? —— unsuccessful 有否定含义，但仍按肯定句处理</li></ul><p><strong>语法</strong>：反义疑问句的基本原则：前肯后否、前否后肯，人称、数、时态保持一致。no、nothing、nobody、never、few、seldom、hardly、rarely、little 具有否定意义，附加问句用肯定式；unsuccessful、dislike、careless 这类否定前后缀不算句法否定，仍按肯定句处理。</p><p>正例：The boy likes playing football, doesn&#39;t he?；She hasn&#39;t finished her homework, has she?；Some plants never bloom, do they?；Everyone enjoyed the party, didn&#39;t they? 反例：Judy hardly joins in any class activities, doesn&#39;t she? ×（hardly 算否定，附加问句用肯定式）；Tom dislikes the book, doesn&#39;t he? 改写成 does he ×（dislike 不算句法否定，仍用否定式附加问） 适用边界：判断分两步：先看有没有句法否定词（hardly、never、little…），再看主语属于哪一类（everybody→they、this→it）。</p><p><strong>口诀</strong>：前肯后否，前否后肯；hardly/never 算否定，unhappy 不算 —— 否定词是词表里那几个小词，带否定前缀的形容词不算在这一类。</p></div><div class="hint-container tip"><p class="hint-container-title">used to、have、need、must 的附加问句</p><p><strong>句意</strong>：Janet used to contribute articles to that famous magazine, didn&#39;t she? 意思是“珍妮特过去常给那家著名杂志投稿，不是吗？”</p><p><strong>拆解</strong></p><ul><li>used to → didn&#39;t / usedn&#39;t；ought to → shouldn&#39;t / oughtn&#39;t</li><li>have 表“拥有”可用 have 或 do；表吃喝、度过、举办以及 have to 用 do；作完成时助动词用 have</li><li>need 作实义动词用 do，作情态动词用 need</li><li>must have done 没有明确过去时间 → hasn&#39;t he（Tom must have visited the Great Wall, hasn&#39;t he?）；有明确过去时间 → weren&#39;t you（You must have been very nervous yesterday, weren&#39;t you?）</li></ul><p><strong>语法</strong>：must 的反义疑问句要按它表达的意思还原真实谓语：mustn&#39;t 表禁止时用 must/may；must 表必须时按课件规则用 needn&#39;t；must 表对现在的推测时按 must 后的实际谓语；must have done 有明确过去时间用 did/was，没有明确过去时间用 have/has。</p><ol><li>must have done + 明确过去时间（yesterday）→ 附加问句用 did/was/were</li><li>must have done 无明确过去时间 → 附加问句用 have/has</li></ol><p>正例：He used to take pictures there, didn&#39;t/usedn&#39;t he?；You must have finished yesterday, didn&#39;t you?；Tom must have visited the Great Wall, hasn&#39;t he?；You needn&#39;t go there, need you? 反例：Tom must have visited the Great Wall, didn&#39;t he? ×（没有明确过去时间，要用 hasn&#39;t）；You must have been very nervous yesterday, haven&#39;t you? ×（有 yesterday，实际谓语是 was nervous） 适用边界：不要机械照抄 must：先问“这里的 must 是禁止、必须还是推测”，推测的还要看谓语后面跟的是 have done 还是 be。</p><p><strong>口诀</strong>：must 表推测要还原真实谓语：有昨天用 did/was，没时间用 have/has —— 找时间标志词，再还原谓语，最后才写附加问句。</p></div><div class="hint-container tip"><p class="hint-container-title">主从复合句看谁、否定前移，以及祈使句的附加问</p><p><strong>句意</strong>：I don&#39;t think he can finish the work on time, can he? 意思是“我认为他不能按时完成工作，是吗？”</p><p><strong>拆解</strong></p><ul><li>一般主从复合句的附加问句与主句对应：She hears that Tommy is going to Tokyo next month, doesn&#39;t she?／Your parents don&#39;t believe what you said, do they?</li><li>主句是第一人称 I/we + think、believe、suppose、expect 等态度动词时，附加问句看宾语从句：I don&#39;t think he can finish…, can he?</li><li>否定前移后按主句的肯否决定附加问句肯否：I don&#39;t think she has heard of the man before, has she?</li><li>Let&#39;s…用 shall we；Let us/me…用 will you；肯定祈使句用 will/won&#39;t you，否定祈使句只用 will you</li></ul><p><strong>语法</strong>：一般主从复合句的附加问句与主句对应；主句为第一人称态度动词时与宾语从句对应；祈使句与 there be 有各自固定的附加问句：Let&#39;s → shall we，Let us/me → will you，肯定祈使 → will/won&#39;t you，否定祈使 → will you，there be 仍以 there 作主语。</p><p>正例：She hears that Tommy is going to Tokyo next month, doesn&#39;t she?；I suppose that he&#39;s serious, isn&#39;t he?；I don&#39;t suppose that he is serious, is he?；Don&#39;t forget, will you?；There is no help for it, is there? 反例：I don&#39;t think he can finish the work on time, do I? ×（否定前移后看宾语从句，用 can he）；Everybody knows the answer, don&#39;t they? 写成 doesn&#39;t they ×（everybody 用 they） 适用边界：两条线先分开：附加问句对主句还是对宾语从句（看主句主语是不是第一人称态度动词）；再把人称、数、时态对齐。</p><p><strong>口诀</strong>：Let&#39;s shall we；Let us/me will you；否定祈使只 will you —— 祈使句的附加问句有固定答案，先认出祈使句，再按 Let&#39;s / Let us / 肯定 / 否定四种情况选。</p></div><p>反义疑问句（附加疑问句）在陈述后附加简短问句，寻求确认。基本原则：<strong>前肯后否，前否后肯；人称、数、时态保持一致。</strong></p><p>The boy likes playing football, <strong>doesn&#39;t he</strong>? 这个男孩喜欢踢足球，不是吗？</p><p>She hasn&#39;t finished her homework, <strong>has she</strong>? 她还没完成作业，是吗？</p><h3 id="_1-特殊主语与否定词" tabindex="-1"><a class="header-anchor" href="#_1-特殊主语与否定词"><span>1. 特殊主语与否定词</span></a></h3><table><thead><tr><th>陈述部分</th><th>附加问句</th><th>例句</th></tr></thead><tbody><tr><td>I am...</td><td>aren&#39;t I?</td><td>I&#39;m as tall as your sister, <strong>aren&#39;t I</strong>? 我和你姐姐一样高，不是吗？</td></tr><tr><td>I am not...</td><td>am I?</td><td>I am not old, <strong>am I</strong>? 我不老，是吗？</td></tr><tr><td>I wish...</td><td>may I?</td><td>I wish to have a word with you, <strong>may I</strong>? 我想和你说句话，可以吗？</td></tr><tr><td>everybody/everyone/someone/somebody</td><td>they</td><td>Everyone enjoyed the party, <strong>didn&#39;t they</strong>? 每个人在聚会上都很开心，不是吗？</td></tr><tr><td>everything/nothing/anything/something/this/that</td><td>it</td><td>Everything seems all right, <strong>doesn&#39;t it</strong>? 一切似乎都没问题，不是吗？</td></tr><tr><td>these/those</td><td>they</td><td>These are your new books, <strong>aren&#39;t they</strong>? 这些是你的新书，不是吗？</td></tr></tbody></table><p><strong>no, nothing, nobody, never, few, seldom, hardly, rarely, little</strong> 等具有否定意义，附加问句用<strong>肯定式</strong>：Some plants never bloom, <strong>do they</strong>? 有些植物从不开花，是吗？</p><div class="hint-container caution"><p class="hint-container-title">易错</p><p>否定前后缀不算句法否定unsuccessful、dislike、careless 等虽有否定含义，陈述部分仍按<strong>肯定句</strong>处理：He was unsuccessful, <strong>wasn&#39;t he</strong>?（他没有成功，是吗？）Tom dislikes the book, <strong>doesn&#39;t he</strong>?（汤姆不喜欢这本书，是吗？）</p></div><h3 id="_2-ought-to、used-to、have、need" tabindex="-1"><a class="header-anchor" href="#_2-ought-to、used-to、have、need"><span>2. ought to、used to、have、need</span></a></h3><table><thead><tr><th>陈述部分</th><th>附加问句</th><th>例句</th></tr></thead><tbody><tr><td>ought to</td><td>shouldn&#39;t / oughtn&#39;t + 主语</td><td>He ought to know what to do, <strong>shouldn&#39;t/oughtn&#39;t he</strong>? 他应该知道做什么，不是吗？</td></tr><tr><td>used to</td><td>didn&#39;t / usedn&#39;t + 主语</td><td>He used to take pictures there, <strong>didn&#39;t/usedn&#39;t he</strong>? 他过去常在那里拍照，不是吗？</td></tr><tr><td>have 表&quot;拥有&quot;</td><td>have 或 do</td><td>He has a new car, <strong>hasn&#39;t/doesn&#39;t he</strong>? 他有一辆新车，不是吗？</td></tr><tr><td>have 表吃喝、度过、举办；have to</td><td>do</td><td>He has supper at home, <strong>doesn&#39;t he</strong>? 他在家吃晚饭，不是吗？</td></tr><tr><td>have 作完成时助动词</td><td>have</td><td>They have known the matter, <strong>haven&#39;t they</strong>? 他们已经知道此事了，不是吗？</td></tr><tr><td>need 作实义动词</td><td>do</td><td>We need to help them, <strong>don&#39;t we</strong>? 我们需要帮助他们，不是吗？</td></tr><tr><td>need 作情态动词</td><td>need</td><td>You needn&#39;t go there, <strong>need you</strong>? 你不必去那里，是吗？</td></tr></tbody></table><h3 id="_3-must-的反义疑问句" tabindex="-1"><a class="header-anchor" href="#_3-must-的反义疑问句"><span>3. must 的反义疑问句</span></a></h3><table><thead><tr><th>must 的含义</th><th>附加问句</th><th>例句</th></tr></thead><tbody><tr><td>mustn&#39;t 表禁止</td><td>must/may + 主语</td><td>You mustn&#39;t stop your car here, <strong>must/may you</strong>? 你不得在此停车，对吧？</td></tr><tr><td>must 表必须</td><td>needn&#39;t + 主语（按课件规则）</td><td>They must finish the work today, <strong>needn&#39;t they</strong>? 他们今天必须完成工作，是吧？</td></tr><tr><td>must 表对现在推测</td><td>按 must 后实际谓语</td><td>He must be good at English, <strong>isn&#39;t he</strong>? 他一定擅长英语，不是吗？</td></tr><tr><td>must have done，有明确过去时间</td><td>did / was/were</td><td>You must have finished yesterday, <strong>didn&#39;t you</strong>? 你昨天一定完成了，不是吗？</td></tr><tr><td>must have done，无明确过去时间</td><td>haven&#39;t/hasn&#39;t</td><td>You must have seen the film already, <strong>haven&#39;t you</strong>? 你一定已经看过电影了，不是吗？</td></tr></tbody></table><p>You must have been very scared yesterday, <strong>weren&#39;t you</strong>? 你昨天一定非常害怕，不是吗？（有 yesterday，实际谓语是 was scared）</p><div class="hint-container caution"><p class="hint-container-title">易错</p><p>mustn&#39;t 不等于&quot;不必&quot;<strong>mustn&#39;t 是&quot;禁止&quot;；&quot;不必&quot;用 needn&#39;t / don&#39;t have to</strong>。表推测时不要机械照抄 must，要还原真实时态和谓语。</p></div><h3 id="_4-there-be-与祈使句" tabindex="-1"><a class="header-anchor" href="#_4-there-be-与祈使句"><span>4. there be 与祈使句</span></a></h3><p>there be 的附加问句仍以 <strong>there</strong> 作主语：There is no help for it, <strong>is there</strong>? 对此没有办法了，是吗？</p><table><thead><tr><th>陈述部分</th><th>附加问句</th></tr></thead><tbody><tr><td>Let&#39;s...（建议）</td><td>shall we?</td></tr><tr><td>Let us/me...（请求允许）</td><td>will you?</td></tr><tr><td>肯定祈使句</td><td>will you / won&#39;t you?</td></tr><tr><td>否定祈使句</td><td>will you?</td></tr></tbody></table><p><strong>Let&#39;s</strong> go home together, <strong>shall we</strong>? 我们一起回家，好吗？</p><p><strong>Let us</strong> stop to rest, <strong>will you</strong>? 让我们停下来休息，好吗？</p><p>Please open the window, <strong>will/won&#39;t you</strong>? 请打开窗户，好吗？</p><p>Don&#39;t forget, <strong>will you</strong>? 别忘了，好吗？</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀<strong>前肯后否，前否后肯；人称时态必须同。祈使附加问：Let&#39;s shall we；Let us/me will you；否定祈使只 will you。</strong></p></div><h3 id="_5-主从复合句与否定前移" tabindex="-1"><a class="header-anchor" href="#_5-主从复合句与否定前移"><span>5. 主从复合句与否定前移</span></a></h3><p>一般主从复合句的附加问句与<strong>主句</strong>对应：</p><p>She says that I did it, <strong>doesn&#39;t she</strong>? 她说是我做的，不是吗？</p><p>I told them not everybody could do it, <strong>didn&#39;t I</strong>? 我告诉他们并非人人都能做到，不是吗？（第一场课独有例句）</p><p>若主句主语是第一人称 I/we，谓语为 <strong>think, believe, suppose, expect, suspect, imagine, consider</strong> 等态度动词，附加问句通常与<strong>宾语从句</strong>对应；否定前移时，根据主句的肯否决定附加问句肯否。</p><p>I suppose that he&#39;s serious, <strong>isn&#39;t he</strong>? 我认为他是认真的，不是吗？</p><p>I don&#39;t suppose that he is serious, <strong>is he</strong>? 我认为他不认真，是吗？</p><p>I think she cares, <strong>doesn&#39;t she</strong>? 我觉得她在意，不是吗？</p><p>I don&#39;t think she cares, <strong>does she</strong>? 我觉得她不在意，是吗？</p><p>I don&#39;t think he will win. 我认为他不会赢。（否定前移；不用 I think he will not win）</p><h3 id="_6-回答反义疑问句-按事实" tabindex="-1"><a class="header-anchor" href="#_6-回答反义疑问句-按事实"><span>6. 回答反义疑问句：按事实</span></a></h3><p>Yes/No 只按<strong>事实本身</strong>回答：事实为肯定用 Yes，事实为否定用 No，不受前句形式影响。</p><p>You aren&#39;t a student, are you? 你不是学生，对吗？ <strong>Yes, I am.</strong> 不，我是学生。 / <strong>No, I&#39;m not.</strong> 对，我不是学生。</p><h2 id="易错清单" tabindex="-1"><a class="header-anchor" href="#易错清单"><span>易错清单</span></a></h2><div class="hint-container caution"><p class="hint-container-title">易错</p><p>高频易错</p><ol><li><p>感叹句先删主谓：<strong>名词 what，形副 how</strong>；单数可数名词检查 a/an</p></li><li><p>强调句只用 <strong>It is/was...that/who...</strong>，不能强调谓语；删去框架后须仍为完整句</p></li><li><p><strong>It was not until...that + 肯定形式</strong>；普通 not until 倒装是&quot;前不倒、后倒&quot;</p></li><li><p>完全倒装遇代词不倒：Here comes the bus，但 Here we are</p></li><li><p><strong>not only...but also 前倒后不倒</strong>；hardly/scarcely...when，no sooner...than</p></li><li><p>only 必须修饰<strong>状语</strong>且置于句首才倒装；only 修饰主语不倒装</p></li><li><p>as/though 让步倒装中，单数可数名词作表语前置时省冠词：Teacher as she is...</p></li><li><p><strong>So + 倒装</strong>是&quot;另一人也一样&quot;；<strong>So + 主语 + 助动词</strong>是&quot;的确如此&quot;</p></li><li><p>反义疑问句先判句法肯否：hardly/never/little 是否定；unhappy/dislike 仍按肯定句</p></li><li><p>must 表推测时还原真实谓语；<strong>must have done + 明确过去时间用 did/was，未明确过去时间用 have/has</strong></p></li><li><p>第一人称态度动词要警惕<strong>否定前移</strong>，附加问句通常看宾语从句；其他主从复合句一般看主句</p></li></ol></div><h2 id="课堂练习" tabindex="-1"><a class="header-anchor" href="#课堂练习"><span>课堂练习</span></a></h2><p><strong>____ interesting life he lives!（他过着多么有趣的生活啊！）</strong></p><ul><li>A. What</li><li>B. What an</li><li>C. How</li><li>D. How an</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（What an）</strong> —— 原题：随堂选择题（教材 P189-190）。课件未附答案，笔记补充解析：划掉主谓后中心词 life 是可数名词单数，且 interesting 以元音音素开头 → What an。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 中心词 life 是可数名词单数，前面必须带冠词，只写 What 缺了 an。干扰点：只顾选 what，忘了冠词。</li><li>B ✅ 划掉句末主谓 he lives 后，剩余部分中心词 life 是可数名词单数，且 interesting 以元音音素开头 → What an。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ How 后面要接形容词或副词（How interesting the life is!），不能直接接名词短语。</li><li>D ❌ how 不与冠词连用，how an 不是结构；只有 how + adj. + a/an + 名词 这种语序。</li></ul><p><strong>整句翻译</strong>：他过着多么有趣的生活啊！</p><p><strong>词组</strong>：<code>live a life</code> 过着……的生活；<code>interesting</code> 有趣的（以元音音素开头，用 an）</p><p><strong>对比自测</strong>：做完后对照 quiz:1，比较两题的判断依据</p><p><strong>原文定位</strong>（课件感叹句口诀）：名词若是可数单，前带冠词 a 或 an</p></details><p><strong>____ amazing the tiny cells are!（这些微小的细胞多么神奇啊！）</strong></p><ul><li>A. How</li><li>B. What</li><li>C. What an</li><li>D. How an</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（How）</strong> —— 原题：随堂选择题（教材 P189-190）。课件未附答案，笔记补充解析：划掉主谓后中心词 amazing 是形容词 → How。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 划掉主谓 the tiny cells are 后，剩下 How amazing，中心词是形容词 → 用 How。来源：课件未附答案，本条为笔记补充解析。</li><li>B ❌ What 后面要接名词（What amazing cells!），不能直接接形容词。</li><li>C ❌ What an 用于“what + a/an + adj. + 单数名词”，本句没有名词。</li><li>D ❌ how 不与 an 连用，How an 不是结构。</li></ul><p><strong>整句翻译</strong>：这些微小的细胞多么神奇啊！</p><p><strong>词组</strong>：<code>tiny cells</code> 微小的细胞；<code>amazing</code> 令人惊讶的、神奇的</p><p><strong>对比自测</strong>：做完后对照 quiz:0，比较两题的判断依据</p><p><strong>原文定位</strong>（课件感叹句口诀）：形副跟在 how 后面，what 身后名词连</p></details><p><strong>It was not until she arrived home ____ she remembered her appointment with her friend.（直到到家，她才想起和朋友的约会。）</strong></p><ul><li>A. then</li><li>B. and</li><li>C. when</li><li>D. that</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（that）</strong> —— 课件原答案：固定结构 It was not until...that...，强调 not...until 时 that 后用肯定形式。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ then 是副词，不能连接从句；强调句的框架词固定是 that。</li><li>B ❌ and 是并列连词，本句不是并列关系，而是 it 强调结构。</li><li>C ❌ when 是副词性的连接词，不进入这个强调框架。干扰点：看到时间内容就填 when。</li><li>D ✅ It was not until...that... 是强调 not...until 的固定结构，that 后用肯定形式 she remembered。</li></ul><p><strong>整句翻译</strong>：直到到家，她才想起和朋友的约会。</p><p><strong>词组</strong>：<code>not...until...</code> 直到……才……；<code>an appointment with sb.</code> 与某人的约会</p><p><strong>对比自测</strong>：做完后对照 quiz:16，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 not...until 的强调）：It is/was not until + 被强调部分 + that + 肯定形式的其余部分</p></details><p><strong>It was ten years ago ____ I met him in the factory where he worked.（我正是在十年前在他工作的工厂里遇见他的。）</strong></p><ul><li>A. since</li><li>B. before</li><li>C. that</li><li>D. when</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（that）</strong> —— 课件原答案：删去 It was...that 后剩余部分仍为完整句，是强调句（强调时间状语 ten years ago）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ since 要与“It is + 时间段”搭配，本句是 ten years ago 这个时间点。干扰点：把 ago 当成 since 的信号。</li><li>B ❌ before 用于 It was (not) + 时间段 + before 结构，后面接的是新出现的情况。</li><li>C ✅ 删去 It was 和 that 后，剩下 I met him in the factory where he worked ten years ago，仍是完整句 → 强调句，用 that 强调时间状语。</li><li>D ❌ when 不能进入强调框架；本句被强调的成分就是 ten years ago。</li></ul><p><strong>整句翻译</strong>：我正是在十年前在他工作的那家工厂里遇见他的。</p><p><strong>词组</strong>：<code>ten years ago</code> 十年前（被强调的时间状语）；<code>meet sb. in the factory</code> 在工厂里遇见某人</p><p><strong>对比自测</strong>：做完后对照 quiz:2，比较两题的判断依据</p><p><strong>原文定位</strong>（课件判断方法）：删去 It is/was 和 that/who 后，剩余部分仍是完整句子，才是强调句</p></details><p><strong>It has been more than five years ____ they met last time in Wuhan.（自从他们上次在武汉见面，已经五年多了。）</strong></p><ul><li>A. since</li><li>B. although</li><li>C. for</li><li>D. until</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（since）</strong> —— 课件原答案：It is/has been + 时间段 + since + 一般过去时 句型。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ It is/has been + 时间段 + since + 一般过去时，表示“自从……已经多久”，这里 has been 配 met。</li><li>B ❌ although 表让步，与时间跨度无关，语义不通。</li><li>C ❌ for 表示持续的时间长度，放在时间段之后不能引导从句。</li><li>D ❌ until 表“直到”，与“已经五年多”的语义不符。</li></ul><p><strong>整句翻译</strong>：自从他们上次在武汉见面，已经五年多了。</p><p><strong>词组</strong>：<code>more than five years</code> 五年多；<code>last time</code> 上次</p><p><strong>对比自测</strong>：做完后对照 quiz:5，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 It 易混句型）：It is/has been + 时间段 + since + 一般过去时</p></details><p><strong>It will be a while ____ we know the results of the experiments.（还要过一段时间我们才会知道实验结果。）</strong></p><ul><li>A. once</li><li>B. before</li><li>C. after</li><li>D. when</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（before）</strong> —— 课件原答案：It will (not) be + 时间段 + before + 一般现在时，表&quot;要过多久才……&quot;。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ once 表“一旦”，强调条件成熟的那一刻，不表时间跨度。</li><li>B ✅ It will be + 时间段 + before + 一般现在时，表示“要过多久才……”，从句用 know。</li><li>C ❌ after 会读成“知道结果之后再过一段时间”，先后颠倒。</li><li>D ❌ when 表“当……时候”，不能表达“要过多久才”的时间跨度。</li></ul><p><strong>整句翻译</strong>：还要过一段时间我们才会知道实验结果。</p><p><strong>词组</strong>：<code>a while</code> 一段时间；<code>the results of the experiments</code> 实验的结果</p><p><strong>对比自测</strong>：做完后对照 quiz:4，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 It 易混句型）：It will (not) be + 时间段 + before + 一般现在时</p></details><p><strong>It isn’t the first time that I ____ myself in an embarrassing situation.（这不是我第一次发现自己处境尴尬。）</strong></p><ul><li>A. have found</li><li>B. found</li><li>C. find</li><li>D. was found</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（have found）</strong> —— 课件原答案：It is/will be the first/second...time + that + 现在完成时。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ It is/will be the first/second...time + that + 现在完成时；主句是 isn&#39;t，从句用 have found。</li><li>B ❌ found 是一般过去时，这个句型要求现在完成时。</li><li>C ❌ find 是一般现在时，表达不出“到现在为止已经不是第一次”。</li><li>D ❌ was found 是被动语态；find oneself 是“发现自己”的主动结构。干扰点：见到 find 就想到被动。</li></ul><p><strong>整句翻译</strong>：这不是我第一次发现自己处境尴尬。</p><p><strong>词组</strong>：<code>find oneself in a situation</code> 发现自己处于某种处境；<code>an embarrassing situation</code> 尴尬的处境</p><p><strong>对比自测</strong>：做完后对照 quiz:7，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 It 易混句型）：It is/will be the first/second...time + that + 现在完成时</p></details><p><strong>It’s high time that you ____ the seriousness of your own mistakes.（你早该认识到自己错误的严重性了。）</strong></p><ul><li>A. have realized</li><li>B. realize</li><li>C. will realize</li><li>D. realized</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（realized）</strong> —— 课件原答案：It is (high) time that + 过去式，用过去式表示虚拟（也可 should do）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ have realized 是现在完成时；It is high time 从句用一般过去时（或 should + 原形）。</li><li>B ❌ realize 是原形/一般现在时，与“早该”的虚拟语气不符。</li><li>C ❌ will realize 是将来时，表达不出“早该认识到”。</li><li>D ✅ It is (high) time that + 过去式，用 realized 表示虚拟；也可以写 should realize，但 should 不可省。</li></ul><p><strong>整句翻译</strong>：你早该认识到自己错误的严重性了。</p><p><strong>词组</strong>：<code>the seriousness of one&#39;s mistakes</code> 某人错误的严重性；<code>It is high time that ...</code> 该做某事的时候了（从句用过去式）</p><p><strong>对比自测</strong>：做完后对照 quiz:6，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 It 易混句型）：It is (high/about) time + that + 过去式 / should do</p></details><p><strong>【22 重庆】It was because of his good performance at the interview ____ he got the job with the big company.（正因为面试表现出色，他才得到那家大公司的工作。）</strong></p><ul><li>A. so</li><li>B. what</li><li>C. that</li><li>D. which</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（that）</strong> —— 课件原答案：强调句 It was...that...，强调原因 because of 短语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ so 是并列连词“所以”，不能进入强调框架。</li><li>B ❌ what 引导名词性从句，不能作强调句的框架词。</li><li>C ✅ 强调句 It was ... that ...，这里强调原因状语 because of his good performance at the interview。（真题：22 重庆）</li><li>D ❌ which 引导定语从句或名词性从句，本句没有先行词，也不是从句作主语或宾语。干扰点：把强调句看成定语从句。</li></ul><p><strong>整句翻译</strong>：正因为面试表现出色，他才得到那家大公司的工作。</p><p><strong>词组</strong>：<code>because of</code> 因为（后接名词性成分）；<code>good performance at the interview</code> 面试中的出色表现</p><p><strong>对比自测</strong>：做完后对照 quiz:38，比较两题的判断依据</p><p><strong>原文定位</strong>（课件强调句基本结构）：强调人时可用 that 或 who，强调非人部分只能用 that</p></details><p><strong>【25 湖南】Not until I had read between the lines ____ the concept.（直到读懂言外之意，我才理解这个概念。）</strong></p><ul><li>A. did I understand</li><li>B. I understood</li><li>C. I did understand</li><li>D. understood I</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（did I understand）</strong> —— 课件原答案：Not until 置于句首，主句部分倒装——&quot;前不倒、后倒&quot;。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ Not until 置于句首，主句部分倒装，借 did → did I understand。（真题：25 湖南）</li><li>B ❌ I understood 是陈述语序；Not until 置首必须倒装。</li><li>C ❌ I did understand 只加了助动词，语序仍未倒装。干扰点：以为加了 did 就算倒装。</li><li>D ❌ understood I 把谓语整个提前，是主谓全倒的错序；部分倒装只提前助动词。</li></ul><p><strong>整句翻译</strong>：直到读懂言外之意，我才理解这个概念。</p><p><strong>词组</strong>：<code>read between the lines</code> 读懂言外之意；<code>the concept</code> 这个概念</p><p><strong>对比自测</strong>：做完后对照 quiz:16，比较两题的判断依据</p><p><strong>原文定位</strong>（课件部分倒装①）：Not until + 时间状语/从句 + 倒装主句：前不倒、后倒</p></details><p><strong>【24 重庆】No sooner had he sat down ____ somebody knocked on the door.（他刚坐下就有人敲门。）</strong></p><ul><li>A. when</li><li>B. then</li><li>C. than</li><li>D. it</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（than）</strong> —— 课件原答案：No sooner...than...（一……就……）；hardly/scarcely 才配 when。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ when 是 hardly/scarcely 的搭档；no sooner 的配对词固定是 than。干扰点：把两组搭配弄混。</li><li>B ❌ then 是副词，不是连词，不能连接从句。</li><li>C ✅ No sooner...than... 表“一……就……”，与句首的倒装 No sooner had 配套。（真题：24 重庆）</li><li>D ❌ it 与结构无关，本句不是强调句。</li></ul><p><strong>整句翻译</strong>：他刚坐下就有人敲门。</p><p><strong>词组</strong>：<code>no sooner...than...</code> 一……就……（配 than）；<code>knock on the door</code> 敲门</p><p><strong>对比自测</strong>：做完后对照 quiz:14，比较两题的判断依据</p><p><strong>原文定位</strong>（课件口诀）：hardly/scarcely 配 when，no sooner 配 than</p></details><p><strong>Only under special circumstances ____ to make up tests.（只有在特殊情况下，学生才获准补考。）</strong></p><ul><li>A. students are permitted</li><li>B. are students permitted</li><li>C. permitted are students</li><li>D. are permitted students</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（are students permitted）</strong> —— 课件原答案（扫描页）：only + 状语（介词短语）置于句首，主句部分倒装——把 be 动词 are 提到主语 students 前，过去分词 permitted 留在主语后。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ students are permitted 是陈述语序；only + 状语置首必须部分倒装。</li><li>B ✅ only + 介词短语置于句首，主句部分倒装：把 be 动词 are 提到主语 students 前，过去分词 permitted 留在后面。</li><li>C ❌ permitted are students 把过去分词也提前了，语序全乱。</li><li>D ❌ are permitted students 把主语放到了句末，不符合部分倒装只提前助动词的规则。</li></ul><p><strong>整句翻译</strong>：只有在特殊情况下，学生才获准补考。</p><p><strong>词组</strong>：<code>under special circumstances</code> 在特殊情况下；<code>make up tests</code> 补考</p><p><strong>对比自测</strong>：做完后对照 quiz:28，比较两题的判断依据</p><p><strong>原文定位</strong>（课件部分倒装②）：only 修饰副词、介词短语或状语从句并置于句首时，主句部分倒装</p></details><p><strong>So fast ____ that none of us could catch up with him.（他跑得如此快，我们谁也追不上。）</strong></p><ul><li>A. did he run</li><li>B. he ran</li><li>C. ran he</li><li>D. he did run</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（did he run）</strong> —— 课件原答案（扫描页）：So 位于句首，主句用部分倒装，借助动词 did 前置。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ So 置于句首引发部分倒装，借 did → did he run。</li><li>B ❌ he ran 是陈述语序；So 前置必须倒装。</li><li>C ❌ ran he 把实义动词整个提前，属于主谓全倒的错序。</li><li>D ❌ he did run 有 did 但没倒装，只是强调语序。</li></ul><p><strong>整句翻译</strong>：他跑得如此快，我们谁也追不上。</p><p><strong>词组</strong>：<code>catch up with sb.</code> 追上、赶上某人；<code>none of us</code> 我们谁都不</p><p><strong>对比自测</strong>：做完后对照 quiz:39，比较两题的判断依据</p><p><strong>原文定位</strong>（课件部分倒装③）：So fast did he run that I couldn&#39;t catch up with him.</p></details><p><strong>____, they often talk with each other by phone.（尽管他们分居两地，却经常打电话交谈。）</strong></p><ul><li>A. Apart as live they</li><li>B. As live they apart</li><li>C. As apart they live</li><li>D. Apart as they live</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（Apart as they live）</strong> —— 课件原答案（扫描页）：as 让步倒装把表语 apart 提到 as 前，其余保持陈述语序。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Apart as live they 把主语与谓语的位置也互换了；as 让步倒装只提前表语，其余保持陈述语序。</li><li>B ❌ As live they apart 语序全乱，as 也没有跟在被提前的成分之后。</li><li>C ❌ As apart they live 把 as 放到了句首，那是“因为/当……时”的结构，不表让步。</li><li>D ✅ as 让步倒装把表语 apart 提到 as 前，其余保持陈述语序：Apart as they live。</li></ul><p><strong>整句翻译</strong>：尽管他们分居两地，却经常打电话交谈。</p><p><strong>词组</strong>：<code>apart</code> 分开地、分居两地；<code>talk with each other</code> 互相交谈</p><p><strong>对比自测</strong>：做完后对照 quiz:17，比较两题的判断依据</p><p><strong>原文定位</strong>（课件让步倒装）：状语提前：Much as/though I like the book, I don&#39;t have enough money to buy it.</p></details><p><strong>Hardly ____ the door when the phone rang.（我刚关门，电话就响了。）</strong></p><ul><li>A. had I closed</li><li>B. I had closed</li><li>C. did I close</li><li>D. I closed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（had I closed）</strong> —— 课件原答案：Hardly...when（刚……就……），Hardly 置于句首 + 过去完成时部分倒装。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ Hardly...when...（刚……就……），Hardly 置于句首用过去完成时部分倒装：had I closed。</li><li>B ❌ I had closed 是陈述语序；Hardly 置首必须倒装。</li><li>C ❌ did I close 时态错：先发生的动作用过去完成时。</li><li>D ❌ I closed 既没倒装，时态也不对。</li></ul><p><strong>整句翻译</strong>：我刚关上门，电话就响了。</p><p><strong>词组</strong>：<code>hardly...when...</code> 刚一……就……（配 when）；<code>the phone rang</code> 电话响了</p><p><strong>对比自测</strong>：做完后对照 quiz:10，比较两题的判断依据</p><p><strong>原文定位</strong>（课件部分倒装①）：Hardly/Scarcely had + 主语 + done when...</p></details><p><strong>Not only ____ to the party, but she also brought a gift.（她不仅来参加聚会，还带了礼物。）</strong></p><ul><li>A. did she come</li><li>B. she came</li><li>C. does she come</li><li>D. she does come</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（did she come）</strong> —— 课件原答案：Not only 分句倒装、but also 分句不倒（前倒后不倒）；后分句 brought 表明是过去时，前分句借 did 倒装。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ Not only 分句倒装、but also 分句不倒（前倒后不倒）；后分句 brought 说明是过去时，前分句借 did 倒装。</li><li>B ❌ she came 是陈述语序；Not only 置首必须倒装。</li><li>C ❌ does she come 时态错——后分句 brought 表明是过去。</li><li>D ❌ she does come 既没倒装，时态也与 brought 不符。</li></ul><p><strong>整句翻译</strong>：她不仅来参加了聚会，还带了礼物。</p><p><strong>词组</strong>：<code>not only...but also...</code> 不仅……而且……；<code>bring a gift</code> 带礼物</p><p><strong>对比自测</strong>：做完后对照 quiz:29，比较两题的判断依据</p><p><strong>原文定位</strong>（课件部分倒装①）：Not only + 倒装分句, but also + 陈述语序分句：前倒后不倒</p></details><p><strong>Not until she received the letter ____ know the truth.（直到收到信，她才知道真相。）</strong></p><ul><li>A. she would</li><li>B. she did</li><li>C. would she</li><li>D. did she</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（did she）</strong> —— 课件原答案：Not until 置于句首，主句部分倒装；know 是动词原形，需借 did 前置。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ she would 是陈述语序，且时态与 received 不搭。</li><li>B ❌ she did 是陈述语序，没有倒装。</li><li>C ❌ would she 倒装了，但 received 是过去时，主句该用 did。</li><li>D ✅ Not until 置于句首，主句部分倒装；know 是动词原形，借 did 前置 → did she know。</li></ul><p><strong>整句翻译</strong>：直到收到信，她才知道真相。</p><p><strong>词组</strong>：<code>receive the letter</code> 收到信；<code>know the truth</code> 知道真相</p><p><strong>对比自测</strong>：做完后对照 quiz:9，比较两题的判断依据</p><p><strong>原文定位</strong>（课件部分倒装①）：Not until + 时间状语/从句 + 倒装主句</p></details><p><strong>____, she is not capable of teaching all subjects at present.（尽管她是老师，目前却不能教所有科目。）</strong></p><ul><li>A. As she is a teacher</li><li>B. Teacher as she is</li><li>C. A teacher as she is</li><li>D. The teacher as is she</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（Teacher as she is）</strong> —— 课件原答案：as/though 让步倒装中，单数可数名词作表语提前时省略冠词——Teacher as she is。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ As she is a teacher 没倒装；as 表“虽然”时必须倒装，否则会被读成“因为/当……”。</li><li>B ✅ as 让步倒装，单数可数名词作表语提前时省略冠词 → Teacher as she is。</li><li>C ❌ A teacher as she is 多了冠词：名词表语提前要去掉冠词。</li><li>D ❌ The teacher as is she 语序全乱，as 后应是“主语 + 谓语”。</li></ul><p><strong>整句翻译</strong>：尽管她是老师，目前却不能教所有科目。</p><p><strong>词组</strong>：<code>be capable of doing sth.</code> 有能力做某事；<code>at present</code> 目前</p><p><strong>对比自测</strong>：做完后对照 quiz:13，比较两题的判断依据</p><p><strong>原文定位</strong>（课件易错）：as/though 让步倒装中，单数可数名词作表语前置时省冠词</p></details><p><strong>Across the river ____. Many people come here to see it.（河对岸横跨着一座新建的桥，许多人来这里看它。）</strong></p><ul><li>A. lies a new built bridge</li><li>B. lies a newly built bridge</li><li>C. a new built bridge lies</li><li>D. a newly built bridge lies</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（lies a newly built bridge）</strong> —— 课件原答案：方位介词短语置于句首引发完全倒装；且副词 newly 修饰 built（new built 是错拼）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ new built 搭配错：修饰过去分词 built 要用副词 newly。</li><li>B ✅ 方位介词短语置于句首引发完全倒装（lies a newly built bridge），且副词 newly 正确修饰 built。</li><li>C ❌ 语序没倒装（a new built bridge lies），且 new built 仍然错。</li><li>D ❌ newly built 对了，但语序没倒装：方位短语置首时主语要跟在谓语之后。</li></ul><p><strong>整句翻译</strong>：河对岸横跨着一座新建的桥，许多人来这里看它。</p><p><strong>词组</strong>：<code>across the river</code> 在河对岸；<code>a newly built bridge</code> 一座新建的桥（newly 是副词，修饰 built）</p><p><strong>对比自测</strong>：做完后对照 quiz:11，比较两题的判断依据</p><p><strong>原文定位</strong>（课件完全倒装）：On the top of the hill stands a temple.</p></details><p><strong>So selfish ____ that everyone avoided talking with her.（她如此自私，以至于人人都避免和她说话。）</strong></p><ul><li>A. he was</li><li>B. was he</li><li>C. she was</li><li>D. was she</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（was she）</strong> —— 课件原答案：So 置于句首引发部分倒装，主语是 she → was she。为与过去时 was 保持一致，主句改为 everyone avoided talking with her。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ he was 语序没倒装，人称也与后文 her 不符。</li><li>B ❌ was he 语序对、人称错（后文是 her）。干扰点：只看语序不看人称。</li><li>C ❌ she was 人称对、语序没倒装。</li><li>D ✅ So 置于句首引发部分倒装，主语是 she → was she。</li></ul><p><strong>整句翻译</strong>：她如此自私，以至于人人都避免和她说话。</p><p><strong>词组</strong>：<code>so selfish</code> 如此自私；<code>avoid doing sth.</code> 避免做某事</p><p><strong>对比自测</strong>：做完后对照 quiz:26，比较两题的判断依据</p><p><strong>原文定位</strong>（课件部分倒装③）：So/Such...that 中 So/Such 置于句首</p></details><p><strong>Judy hardly joins in any class activities, ____?（朱迪几乎不参加任何班级活动，是吗？）</strong></p><ul><li>A. does she</li><li>B. doesn’t she</li><li>C. didn’t she</li><li>D. is she</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（does she）</strong> —— 课件原答案（扫描页）：hardly 已有否定含义，附加问句用肯定式；joins 是一般现在时实义动词 → does she。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ hardly 已有否定含义，附加问句用肯定式；joins 是一般现在时实义动词 → does she。</li><li>B ❌ doesn&#39;t she 又否定一遍：hardly 已经算否定，附加问句要用肯定式。</li><li>C ❌ didn&#39;t she 时态错——joins 是一般现在时。</li><li>D ❌ is she 用 be 动词，与实义动词 joins 不搭。</li></ul><p><strong>整句翻译</strong>：朱迪几乎不参加任何班级活动，是吗？</p><p><strong>词组</strong>：<code>join in</code> 参加（活动）；<code>hardly</code> 几乎不（否定副词）</p><p><strong>对比自测</strong>：做完后对照 quiz:24，比较两题的判断依据</p><p><strong>原文定位</strong>（课件特殊主语与否定词）：no, nothing, nobody, never, few, seldom, hardly, rarely, little 等具有否定意义，附加问句用肯定式</p></details><p><strong>Janet used to contribute articles to that famous magazine, ____?（珍妮特过去常给那家著名杂志投稿，不是吗？）</strong></p><ul><li>A. didn’t she</li><li>B. did she</li><li>C. used she</li><li>D. wouldn’t she</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（didn’t she）</strong> —— 课件原答案（扫描页）：used to 的附加问句可用 didn’t/usedn’t；选项中只有 didn’t she。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ used to 的附加问句可用 didn&#39;t/usedn&#39;t；选项中只有 didn&#39;t she。</li><li>B ❌ did she 是肯定式，而陈述部分是肯定的 used to，附加问句要用否定式。</li><li>C ❌ used she 不是合法形式（否定要写 usedn&#39;t）。</li><li>D ❌ wouldn&#39;t she 与 used to 不搭：would 表意愿或过去将来。</li></ul><p><strong>整句翻译</strong>：珍妮特过去常给那家著名杂志投稿，不是吗？</p><p><strong>词组</strong>：<code>used to do sth.</code> 过去常常做某事；<code>contribute articles to</code> 向……投稿</p><p><strong>对比自测</strong>：做完后对照 quiz:34，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 used to）：used to：didn&#39;t / usedn&#39;t + 主语</p></details><p><strong>Let’s go for a picnic tomorrow, ____?（咱们明天去野餐，好吗？）</strong></p><ul><li>A. shall we</li><li>B. will you</li><li>C. can we</li><li>D. could you</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（shall we）</strong> —— 课件原答案（扫描页）：Let’s（建议，包含听话人）的附加问句用 shall we。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ Let&#39;s 表建议、包含听话人，附加问句用 shall we。</li><li>B ❌ will you 是 Let us/me（请求对方允许）的搭档，不是 Let&#39;s。干扰点：Let&#39;s 与 Let us 只差一个撇号。</li><li>C ❌ can we 不用于 Let&#39;s 的附加问句。</li><li>D ❌ could you 把主语换成了 you，与 Let&#39;s 包含听话人的含义不符。</li></ul><p><strong>整句翻译</strong>：咱们明天去野餐，好吗？</p><p><strong>词组</strong>：<code>go for a picnic</code> 去野餐；<code>Let&#39;s</code> 让我们（包含听话人，附加问句用 shall we）</p><p><strong>对比自测</strong>：做完后对照 quiz:36，比较两题的判断依据</p><p><strong>原文定位</strong>（课件口诀（祈使附加问））：Let’s shall we；Let us/me will you；否定祈使只 will you</p></details><p><strong>Your parents don’t believe what you said, ____?（你的父母不相信你说的话，是吗？）</strong></p><ul><li>A. did they</li><li>B. do they</li><li>C. did you</li><li>D. don’t they</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（do they）</strong> —— 课件原答案（扫描页）：一般主从复合句的附加问句与主句对应——Your parents don’t believe 是一般现在时否定 → do they。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ did they 时态错：主句 don&#39;t believe 是一般现在时。干扰点：被宾语从句的 said 带跑了时态。</li><li>B ✅ 一般主从复合句的附加问句与主句对应：Your parents don&#39;t believe 是一般现在时否定 → do they。</li><li>C ❌ did you 把主语也换成了从句里的 you，附加问句应对主句主语 your parents。</li><li>D ❌ don&#39;t they 与主句同向否定，违背“前否后肯”。</li></ul><p><strong>整句翻译</strong>：你的父母不相信你说的话，是吗？</p><p><strong>词组</strong>：<code>believe sb.</code> 相信某人说的话；<code>what you said</code> 你说的话（宾语从句）</p><p><strong>对比自测</strong>：做完后对照 quiz:27，比较两题的判断依据</p><p><strong>原文定位</strong>（课件主从复合句）：一般主从复合句的附加问句与主句对应</p></details><p><strong>He has never been to Beijing, ____?（他从未去过北京，是吗？）</strong></p><ul><li>A. has he</li><li>B. hasn’t he</li><li>C. does he</li><li>D. doesn’t he</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（has he）</strong> —— 课件原答案：never 是否定词，附加问句用肯定式；been 表明是完成时 → has he。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ never 是否定词，附加问句用肯定式；been 表明是完成时 → has he。</li><li>B ❌ hasn&#39;t he 与 never 同向否定，违背前否后肯。</li><li>C ❌ does he 用错助动词：has been to 是现在完成时。</li><li>D ❌ doesn&#39;t he 既错助动词又错肯否。</li></ul><p><strong>整句翻译</strong>：他从未去过北京，是吗？</p><p><strong>词组</strong>：<code>have been to</code> 去过（某地）；<code>never</code> 从未（否定词）</p><p><strong>对比自测</strong>：做完后对照 quiz:20，比较两题的判断依据</p><p><strong>原文定位</strong>（课件否定词）：Some plants never bloom, do they?</p></details><p><strong>I don’t think he can finish the work on time, ____?（我认为他不能按时完成工作，是吗？）</strong></p><ul><li>A. can he</li><li>B. can’t he</li><li>C. do I</li><li>D. don’t I</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（can he）</strong> —— 课件原答案：第一人称态度动词发生否定前移，附加问句看宾语从句 he can，并用肯定式。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 第一人称态度动词发生否定前移，附加问句看宾语从句 he can，并用肯定式 → can he。</li><li>B ❌ can&#39;t he 又用否定式：否定前移后附加问句按主句的否定走肯定式。</li><li>C ❌ do I 把附加问句对到了主句；这里有否定前移，应对宾语从句。</li><li>D ❌ don&#39;t I 同样对错主句，且同向否定。</li></ul><p><strong>整句翻译</strong>：我认为他不能按时完成工作，是吗？</p><p><strong>词组</strong>：<code>on time</code> 按时；<code>I don&#39;t think ...</code> 我认为……不（否定前移）</p><p><strong>对比自测</strong>：做完后对照 quiz:30，比较两题的判断依据</p><p><strong>原文定位</strong>（课件否定前移）：若主句主语是第一人称 I/we，谓语为 think, believe, suppose, expect, suspect, imagine, consider 等态度动词，附加问句通常与宾语从句对应</p></details><p><strong>—Mia had a wonderful time at the party. —____, and so did I.（——米娅在聚会上玩得很开心。——确实如此，我也一样。）</strong></p><ul><li>A. So she had</li><li>B. So had she</li><li>C. So she did</li><li>D. So did she</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（So she did）</strong> —— 课件原答案：So + 主语 + 助动词 表&quot;确实如此&quot;，不倒装；had a wonderful time 的 have 是实义动词，借 did → So she did。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ So she had 用错助动词：had a wonderful time 里的 have 是实义动词，借 did。</li><li>B ❌ So had she 是倒装的“她也一样”，与后面的 and so did I 重复，逻辑不通。</li><li>C ✅ So + 主语 + 助动词 表“确实如此”，不倒装；had a wonderful time 的 have 是实义动词，借 did → So she did。</li><li>D ❌ So did she 是“她也一样”的倒装形式，与后面的 so did I 撞车。</li></ul><p><strong>整句翻译</strong>：“米娅在聚会上玩得很开心。”“确实如此，我也一样。”</p><p><strong>词组</strong>：<code>have a wonderful time</code> 玩得很开心；<code>so did I</code> 我也一样（倒装）</p><p><strong>对比自测</strong>：做完后对照 quiz:19，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 so 的两副面孔）：So + 倒装 是“另一人也一样”；So + 主语 + 助动词 是“的确如此”</p></details><p><strong>She hears that Tommy is going to Tokyo next month, ____?（她听说汤米下个月要去东京，是吗？）</strong></p><ul><li>A. do she</li><li>B. don’t she</li><li>C. isn’t she</li><li>D. doesn’t she</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（doesn’t she）</strong> —— 课件原答案：一般主从复合句的附加问句与主句对应——She hears 是一般现在时实义动词 → doesn’t she。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ do she 主谓不一致：第三人称单数要用 does。</li><li>B ❌ don&#39;t she 同样主谓不一致。</li><li>C ❌ isn&#39;t she 用 be 动词，而主句谓语是实义动词 hears。</li><li>D ✅ 一般主从复合句的附加问句与主句对应——She hears 是一般现在时实义动词 → doesn&#39;t she。</li></ul><p><strong>整句翻译</strong>：她听说汤米下个月要去东京，是吗？</p><p><strong>词组</strong>：<code>hear that ...</code> 听说……；<code>be going to do sth.</code> 打算做某事</p><p><strong>对比自测</strong>：做完后对照 quiz:23，比较两题的判断依据</p><p><strong>原文定位</strong>（课件主从复合句）：She says that I did it, doesn&#39;t she?</p></details><p><strong>Only when the war was over in 1945 ____ to his hometown.（直到 1945 年战争结束后，他才回到故乡。）</strong></p><ul><li>A. he returned</li><li>B. did he return</li><li>C. he did return</li><li>D. had he returned</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（did he return）</strong> —— 课件原答案：only + 状语从句置于句首，主句部分倒装，借 did。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ he returned 是陈述语序；only + 状语从句置首必须部分倒装。</li><li>B ✅ only + 状语从句置于句首，主句部分倒装，借 did → did he return。</li><li>C ❌ he did return 只加了 did，语序仍未倒装。</li><li>D ❌ had he returned 倒装了，但时态错：only when 从句用一般过去时，主句也是一般过去时。</li></ul><p><strong>整句翻译</strong>：直到 1945 年战争结束后，他才回到故乡。</p><p><strong>词组</strong>：<code>be over</code> 结束；<code>return to one&#39;s hometown</code> 回到故乡</p><p><strong>对比自测</strong>：做完后对照 quiz:11，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 only 置首）：Only when the girl left him did he realize how deeply he loved her.</p></details><p><strong>Not only ____ her how to do this thing but he offered to help her as well.（他不仅教她怎么做，还主动提出帮助她。）</strong></p><ul><li>A. did he show</li><li>B. does he show</li><li>C. he shows</li><li>D. he showed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（did he show）</strong> —— 课件原答案：Not only 分句部分倒装；but 分句 offered 表明是过去时，前分句借 did 倒装。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ Not only 分句部分倒装；but 分句 offered 表明是过去时，前分句借 did 倒装 → did he show。</li><li>B ❌ does he show 时态错（应为过去）。</li><li>C ❌ he shows 既没倒装，时态也错。</li><li>D ❌ he showed 时态对，但 Not only 置首必须倒装。</li></ul><p><strong>整句翻译</strong>：他不仅教她怎么做这件事，还主动提出帮助她。</p><p><strong>词组</strong>：<code>offer to do sth.</code> 主动提出做某事；<code>as well</code> 也</p><p><strong>对比自测</strong>：做完后对照 quiz:15，比较两题的判断依据</p><p><strong>原文定位</strong>（课件部分倒装①）：Not only does he study hard, but he also helps others in study.</p></details><p><strong>I don’t think she has heard of the man before, ____?（我认为她以前没听说过这个人，是吗？）</strong></p><ul><li>A. don’t I</li><li>B. do I</li><li>C. hasn’t she</li><li>D. has she</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（has she）</strong> —— 课件原答案：第一人称态度动词否定前移，附加问句看宾语从句 she has heard，并用肯定式 → has she。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ don&#39;t I 把附加问句对到了主句；否定前移时应看宾语从句。</li><li>B ❌ do I 同样对错主句（应为宾语从句 she has heard）。</li><li>C ❌ hasn&#39;t she 看对了从句，但用否定式；否定前移后附加问句要用肯定式。</li><li>D ✅ 第一人称态度动词否定前移，附加问句看宾语从句 she has heard，并用肯定式 → has she。</li></ul><p><strong>整句翻译</strong>：我认为她以前没听说过这个人，是吗？</p><p><strong>词组</strong>：<code>hear of sb.</code> 听说过某人；<code>before</code> 以前</p><p><strong>对比自测</strong>：做完后对照 quiz:25，比较两题的判断依据</p><p><strong>原文定位</strong>（课件否定前移）：I don&#39;t suppose that he is serious, is he?</p></details><p><strong>Go and get some water and food for these poor old people, ____?（去给这些可怜的老人拿些水和食物，好吗？）</strong></p><ul><li>A. don’t you</li><li>B. shall you</li><li>C. couldn’t you</li><li>D. won’t you</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（won’t you）</strong> —— 课件原答案：肯定祈使句的附加问句用 will you / won’t you。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ don&#39;t you 不是祈使句的附加问句形式。</li><li>B ❌ shall you 没有这个用法（shall 用于 Let&#39;s 的附加问句或第一人称）。</li><li>C ❌ couldn&#39;t you 把情态动词换成了 could，不符合祈使句附加问句的固定形式。</li><li>D ✅ 肯定祈使句的附加问句用 will you / won&#39;t you；这里带“请求、邀请”的意味，won&#39;t you 自然。</li></ul><p><strong>整句翻译</strong>：去给这些可怜的老人拿些水和食物，好吗？</p><p><strong>词组</strong>：<code>go and get sth.</code> 去拿某物；<code>poor old people</code> 可怜的老人</p><p><strong>对比自测</strong>：做完后对照 quiz:22，比较两题的判断依据</p><p><strong>原文定位</strong>（课件祈使句附加问表）：肯定祈使句：will you / won’t you?</p></details><p><strong>____ a strange plant! I have never seen one like this before.（多么奇怪的植物啊！我以前从未见过这样的。）</strong></p><ul><li>A. Which</li><li>B. What</li><li>C. How</li><li>D. Whether</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（What）</strong> —— 课件原答案：感叹句中心词 plant 是名词 → What；题中已给出 a strange，故不选 What a 形式。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Which 表“哪一个”，不引导感叹句。</li><li>B ✅ 感叹句中心词 plant 是名词 → 用 What；题中已给出 a strange，所以前面不再重复 a。</li><li>C ❌ How 后面要接形容词或副词，不能直接接名词短语。</li><li>D ❌ Whether 引导名词性从句表“是否”，与感叹无关。</li></ul><p><strong>整句翻译</strong>：多么奇怪的植物啊！我以前从未见过这样的。</p><p><strong>词组</strong>：<code>a strange plant</code> 一种奇怪的植物；<code>one like this</code> 像这样的一个</p><p><strong>对比自测</strong>：做完后对照 quiz:37，比较两题的判断依据</p><p><strong>原文定位</strong>（课件感叹句）：What + a/an + adj. + n. (+ 主语 + 谓语)!</p></details><p><strong>Mary ____ like surfing the Internet. She often spends hours online.（玛丽确实喜欢上网；她常常一上就是几个小时。）</strong></p><ul><li>A. did</li><li>B. does</li><li>C. do</li><li>D. is</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（does）</strong> —— 课件原答案：does 强调一般现在时谓语 like（&quot;确实喜欢&quot;），主语 Mary 用 does。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ did 是过去时，而后半句用 spends（一般现在时）。</li><li>B ✅ does 强调一般现在时的谓语 like（“确实喜欢”），主语 Mary 是第三人称单数。</li><li>C ❌ do 用于第一、二人称或复数主语，与 Mary 不搭。</li><li>D ❌ is 是系动词，不能用来强调实义动词 like。</li></ul><p><strong>整句翻译</strong>：玛丽确实喜欢上网；她常常一上就是几个小时。</p><p><strong>词组</strong>：<code>like doing sth.</code> 喜欢做某事；<code>spend hours online</code> 花几个小时上网</p><p><strong>对比自测</strong>：做完后对照 quiz:38，比较两题的判断依据</p><p><strong>原文定位</strong>（课件强调句补充讲解）：谓语动词本身要强调时，不用 It 结构，而用助动词 do / does / did + 动词原形：Mary does like surfing the Internet.</p></details><p><strong>Tom must have visited the Great Wall with his parents, ____?（汤姆一定和父母参观过长城，是吗？）</strong></p><ul><li>A. didn’t he</li><li>B. hasn’t he</li><li>C. mustn’t he</li><li>D. wasn’t he</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（hasn’t he）</strong> —— 课件原答案：must have done 无明确过去时间时，附加问句用 hasn’t。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ didn&#39;t he 需要句中有明确的过去时间（如 yesterday），本句没有。干扰点：见到 have visited 就用 did。</li><li>B ✅ must have done 且没有明确过去时间时，附加问句用 hasn&#39;t。</li><li>C ❌ mustn&#39;t he 直接照抄 must；must 表推测时要还原真实谓语。</li><li>D ❌ wasn&#39;t he 与 have visited 的谓语形式不符。</li></ul><p><strong>整句翻译</strong>：汤姆一定和父母参观过长城，是吗？</p><p><strong>词组</strong>：<code>must have done</code> 一定做过（对过去的肯定推测）；<code>the Great Wall</code> 长城</p><p><strong>对比自测</strong>：做完后对照 quiz:35，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 must 的附加问句）：must have done，无明确过去时间 → haven&#39;t/hasn&#39;t</p></details><p><strong>You must have been very nervous in the speech competition yesterday, ____?（你昨天参加演讲比赛时一定很紧张，不是吗？）</strong></p><ul><li>A. weren’t you</li><li>B. mustn’t you</li><li>C. didn’t you</li><li>D. haven’t you</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（weren’t you）</strong> —— 课件原答案：有明确过去时间 yesterday，且实际谓语是 was nervous → weren’t you。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 有明确过去时间 yesterday，且实际谓语是 was nervous → weren&#39;t you。</li><li>B ❌ mustn&#39;t you 直接照抄 must，没有还原真实谓语。干扰点：把情态动词当成句子谓语。</li><li>C ❌ didn&#39;t you 用于实义动词的过去式；这里真实谓语是 be 动词。</li><li>D ❌ haven&#39;t you 忽略了 yesterday 这个明确过去时间。</li></ul><p><strong>整句翻译</strong>：你昨天参加演讲比赛时一定很紧张，不是吗？</p><p><strong>词组</strong>：<code>the speech competition</code> 演讲比赛；<code>must have been</code> 当时一定是（对过去的推测）</p><p><strong>对比自测</strong>：做完后对照 quiz:34，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 must 的附加问句）：You must have been very scared yesterday, weren&#39;t you?</p></details><p><strong>Let’s go on a picnic this weekend, ____? —I want to relax.（我们这周末去野餐，好吗？——我想放松一下。）</strong></p><ul><li>A. will we</li><li>B. shall we</li><li>C. would we</li><li>D. should we</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（shall we）</strong> —— 课件原答案：Let’s 建议句的附加问句用 shall we。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ will we 不用于 Let&#39;s；will you 才是 Let us/me 的搭档。</li><li>B ✅ Let&#39;s 建议句的附加问句用 shall we。</li><li>C ❌ would we 没有这个用法。</li><li>D ❌ should we 不符合该结构的固定形式。</li></ul><p><strong>整句翻译</strong>：我们这周末去野餐，好吗？——我想放松一下。</p><p><strong>词组</strong>：<code>go on a picnic</code> 去野餐；<code>relax</code> 放松</p><p><strong>对比自测</strong>：做完后对照 quiz:22，比较两题的判断依据</p><p><strong>原文定位</strong>（课件祈使句附加问）：Let&#39;s go home together, shall we?</p></details><p><strong>____ valuable book he brought! You should be grateful to him.（他带来的书多么珍贵啊！你应该感谢他。）</strong></p><ul><li>A. What a</li><li>B. What</li><li>C. How a</li><li>D. How</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（What a）</strong> —— 课件原答案：感叹句中心词 book 是可数名词单数 → What a；valuable 以辅音音素开头用 a。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 中心词 book 是可数名词单数 → What a；valuable 以辅音音素开头，用 a。</li><li>B ❌ What 缺冠词：单数可数名词前必须带 a/an。</li><li>C ❌ How a 不是结构；how 只能与形容词、副词搭配。</li><li>D ❌ How 后面要接形容词或副词，不能直接接名词短语。</li></ul><p><strong>整句翻译</strong>：他带来的书多么珍贵啊！你应该感谢他。</p><p><strong>词组</strong>：<code>valuable</code> 珍贵的（以辅音音素开头，用 a）；<code>be grateful to sb.</code> 感谢某人</p><p><strong>对比自测</strong>：做完后对照 quiz:32，比较两题的判断依据</p><p><strong>原文定位</strong>（课件感叹句）：名词若是可数单，前带冠词 a 或 an</p></details><p><strong>It is my grandma ____ brings me up and teaches me much about life.（正是我的奶奶抚养我，并教会我许多人生道理。）</strong></p><ul><li>A. what</li><li>B. who</li><li>C. where</li><li>D. when</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（who）</strong> —— 课件原答案：强调句强调人时可用 that 或 who。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ what 不能进入强调框架。</li><li>B ✅ 强调句强调人时可用 that 或 who，这里指 my grandma 用 who。</li><li>C ❌ where 表地点，本句强调的是人。</li><li>D ❌ when 表时间，与句子内容不符。</li></ul><p><strong>整句翻译</strong>：正是我的奶奶抚养我长大，并教会我许多人生道理。</p><p><strong>词组</strong>：<code>bring sb. up</code> 抚养某人长大；<code>teach sb. much about life</code> 教会某人许多人生道理</p><p><strong>对比自测</strong>：做完后对照 quiz:8，比较两题的判断依据</p><p><strong>原文定位</strong>（课件强调句基本结构）：强调人时可用 that 或 who，强调非人部分只能用 that</p></details><p><strong>So little ____ about British history that the lecture was completely beyond me.（我对英国历史知之甚少，以至于完全听不懂这场讲座。）</strong></p><ul><li>A. do I know</li><li>B. I knew</li><li>C. did I know</li><li>D. I know</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（did I know）</strong> —— 课件原答案：So little（半否定）置于句首引发部分倒装；主句 was beyond me 表明是过去时 → did I know。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ do I know 时态错：主句 was beyond me 是过去时。</li><li>B ❌ I knew 是陈述语序，So little 置首必须倒装。</li><li>C ✅ So little（半否定）置于句首引发部分倒装；主句 was beyond me 表明是过去时 → did I know。</li><li>D ❌ I know 既没倒装又时态错。</li></ul><p><strong>整句翻译</strong>：我对英国历史知之甚少，以至于这场讲座我完全听不懂。</p><p><strong>词组</strong>：<code>so little</code> 如此少（表数量的半否定）；<code>be beyond sb.</code> 超出某人的理解范围</p><p><strong>对比自测</strong>：做完后对照 quiz:12，比较两题的判断依据</p><p><strong>原文定位</strong>（课件部分倒装③）：So fast did he run that I couldn&#39;t catch up with him.</p></details><h2 id="口诀卡" tabindex="-1"><a class="header-anchor" href="#口诀卡"><span>口诀卡</span></a></h2><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>本课全部口诀 感叹句：<strong>形副 how，名词 what；可数单数 a/an 莫忘。</strong></p><p>强调句：<strong>It is/was 框起来，删框完整才算对。</strong></p><p>倒装句：<strong>全倒谓语全提前，部分只提助情系。</strong></p><p>否定句首：<strong>Not until 前不倒后倒，not only 前倒后不倒。</strong></p><p>关联词：<strong>hardly/scarcely 配 when，no sooner 配 than。</strong></p><p>反义疑问：<strong>前肯后否，前否后肯；人称时态必须同。</strong></p><p>祈使附加问：<strong>Let&#39;s shall we；Let us/me will you；否定祈使只 will you。</strong></p></div><p>延伸阅读：特殊句式 · 完整笔记 · 原始课件 PDF</p><p>有不懂的随时问你的 AI 老师——回到 ZCode 对话里直接提问即可。</p><hr>`,302),a(`p`,null,[o(m,{href:`/courses/zsb-english/l/15/`},{default:i(()=>[...l[5]||=[e(`← 第 15 课`,-1)]]),_:1}),l[8]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/`},{default:i(()=>[...l[6]||=[e(`课程目录`,-1)]]),_:1}),l[9]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/17/`},{default:i(()=>[...l[7]||=[e(`第 17 课 →`,-1)]]),_:1})])])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};